INSERT INTO himnos (id, title, description, musical_note, paragraphs, chorus, filename)
VALUES
('e0e52894-0bb4-5124-a726-641273fc4783', 'ÉL HA SIDO FIEL', 'Día a día Tú has sido fiel, no has cambiado y no', 'D|Re', '[{"id": "feadc331-5ec3-d5ee-eea6-3af1b1bcbcad", "paragraph": "Día a día Tú has sido fiel, no has cambiado\ny no cambiarás\nMaravillado estoy con tu amor porque me\namaste siendo un pecador", "chorusPos": [[0]]}, {"id": "75de8fe2-1b63-032e-a7a1-3aeee24a01c8", "paragraph": "Cuando recuerdo mi vida sin ti, sin\nesperanza en sombras viví\nMás hoy reboso en gracia y perdón, porque\nadoptaste a un vil pecador", "chorusPos": [[1]]}, {"id": "4373f22b-63d9-068d-8181-0e4f26e47a32", "paragraph": "Cuando en prueba te exaltaré,\ny cuando duela en ti confiaré\nPorque conozco tu inmensa bondad y sé\nque nunca me abandonarás", "chorusPos": [[1]]}, {"id": "4f6dc50f-d595-1e28-857e-27a047d7f4ca", "paragraph": "Toda mi vida la pongo a tus pies, has lo\nque quieras con ella mi Rey\nHasta que vuelvas con fe cantaré,\n“Día a día tú has sido fiel”", "chorusPos": [[1]]}]'::jsonb, '[{"choir": "Te alabaré, te glorificaré\nPorque agradecido estoy\npor tu inmenso amor\nTe alabaré, te glorificaré\nPorque tu hijo soy, te alabaré", "id": "7ea5eaf9-7524-e8a3-2574-3e9ad3e03ade"}]'::jsonb, 'ÉL HA SIDO FIEL.json'),
('e4d393b2-74fa-ad36-4d43-57efd15579df', 'FUI HECHO JUSTO', 'Fui hecho justo sin merecerlo toda mi culpa ya c', 'G|Sol', '[{"id": "049c564e-eeea-f894-5a91-1caa805b336c", "paragraph": "Fui hecho justo sin merecerlo\ntoda mi culpa ya cubierta esta.\nToda mi deuda quedó saldada,\npor la persona del cordero inmortal.", "chorusPos": [[1]]}, {"id": "7abf7533-4b7f-be97-0603-bcaf6191d69f", "paragraph": "Regenerado y transformado,\n          Cambio mi mente y mi forma de actuar.\n          Hoy solo quiero servir a Cristo,\n          Y ser la luz la sal de un claro manantial.", "chorusPos": [[1]]}]'::jsonb, '[{"choir": "Salvación, camino angosto,\n          Plenitud incomparable don de Dios.\n          Una cruz cubierta en sangre.\n          Fue necesaria para nuestra redención.", "id": "7990fd50-d0b5-b7ab-f402-5fff281110fa"}]'::jsonb, 'Fui Hecho Justo.json'),
('c6ce2ee1-8405-29c8-d77b-c86e7baed8a7', 'VIVIR ES CRISTO', 'Como recibiré de ti el bien, Y el mal rechazare.', 'G|Sol', '[{"id": "1cbf6275-2cde-4c53-ff41-21e80ddde955", "paragraph": "Como recibiré de ti el bien,\nY el mal rechazare.\nSí se que tú eres Señor\nSoberano y justo.", "chorusPos": [[0]]}, {"id": "e547d2cd-f45f-bcc0-92c2-3b00c26f1099", "paragraph": "Como he de alabarte en bendición\ny olvidarte en dolor.\nSi sé que tienes el control,\nde toda tu creación.", "chorusPos": [[0]]}, {"id": "89d1a1fc-0fcc-09b2-b36e-d4992b43cce5", "paragraph": "Como he de creer en ti al tener, y dudar en la escasez\nSi sé que tú eres siempre fiel, y que nunca cambias.\nComo he de seguir en libertad y huir en la opresión\nSi sé que guardas para mí una eterna posesión.", "chorusPos": [[1]]}, {"id": "9786e116-ebd4-755c-3b11-e049c4c8cdcf", "paragraph": "Como he de confiar en tu bondad y tu gran amor por mí,\nSi enviaste a Jesús en mi lugar a morir en una Cruz.\n//Tu gracia es suficiente//", "chorusPos": [[1]]}, {"id": "e06586a3-a83b-06ba-ab10-dd7a5ec71736", "paragraph": "Fija mis ojos solo en ti en lo eterno, en el\ncielo\nLa aflicción de este mundo jamás se\ncompara con la gloria que ha de venir.\n//Vivir es Cristo, vivir es Cristo//", "chorusPos": [[1], [2]]}]'::jsonb, '[{"choir": "Bendito sea el nombre del Señor, en todo tiempo\nSe haga tu perfecta voluntad, en mí.\nDaré gloria a tu nombre a través de mi aflicción\nDame tu gracia para ver: que vivir es Cristo.", "id": "0fd6c903-3093-07f6-8677-46bdd6a1b266"}, {"choir": "…VIVIR ES CRISTO", "id": "6082b4b8-4825-4195-dd28-167462478add"}]'::jsonb, 'VIVIR ES CRISTO.json'),
('0c41c5ca-9067-4902-9693-a580e7ae55da', 'EN TI CONFÍA MI CORAZÓN', 'EN TI CONFÍA MI CORAZÓN    EN TI ...', '--', '[{"paragraph": "EN TI CONFÍA MI CORAZÓN  \n EN TI SE GOZA MI ALMA  \n MI SER DESCANSA EN TI  \n PUEDO SER FELIZ"}, {"paragraph": "POR QUE SE QUE ESTAS OBRANDO TU PERFECTA VOLUNTAD, \n EN MI VIDA ESTAS OBRANDO TU PERFECTA VOLUNTAD"}]'::jsonb, '[]'::jsonb, 'EN TI CONFÍA MI CORAZÓN.json'),
('be04759c-17e4-44fe-99eb-33b9daa89805', 'Eran cien ovejas de un rebaño', 'Eran cien ovejas de un rebaño   e...', '--', '[{"paragraph": "Eran cien ovejas de un rebaño \n eran cienovejas que el      cuido pero una trade al contarlas todas le faltaba una \n esas misma historia vuevle a repetirse \n pero todavia existe el pastro que por las malñas a buscarlas va \n y cuando las alla las trae al camino , al camino bueno de verdad y vida  \n Las cien ovejas"}]'::jsonb, '[]'::jsonb, 'Eran cien ovejas de un rebaño.json'),
('3eb6faaa-acd7-4c58-ba13-326cec666a0b', 'Cuan bello es el señor', '/Cuan bello    es el señor/   cua...', '--', '[{"paragraph": "/Cuan bello  \n es el señor/ \n cuan hermoso es el señor, \n hoy le quiero adorar"}, {"paragraph": "la belleza de mi señor,  \n nunca se agotara,  \n La hermosura  \n de mi señor, \n siempre resplandecerá."}]'::jsonb, '[]'::jsonb, 'Cuan bello es el señor.json'),
('137e347b-01cd-4395-9cbc-7db64a5791c4', 'Digno es el', 'DIGNO ES EL    (APOCALIPSIS 4:8)...', '--', '[{"paragraph": "DIGNO ES EL  \n (APOCALIPSIS 4:8)"}, {"paragraph": "/Digno es el cordero Santo; \n Santo, Santo es Él.  \n Levantamos nuestra alabanza, \n al que en el trono está./"}, {"paragraph": "Santo, Santo, Santo, Dios todopoderoso,  \n quien fue quien es y quien vendrá. \n La creación hoy canta y damos gloria a Él,  \n Tu eres digno por siempre y siempre."}, {"paragraph": "Digno es el cordero Santo; \n Santo, Santo es Él.  \n Levantamos nuestra alabanza, \n al que en el trono está."}, {"paragraph": "/Santo, Santo, Santo, Dios todopoderoso,  \n quien fue quien es y quien vendrá. \n La creación hoy canta y damos gloria a Él,  \n Tu eres digno por siempre y siempre./"}]'::jsonb, '[]'::jsonb, 'Digno es el.json'),
('42d2e024-b348-4083-a520-b0aaeffba221', 'CRISTO ME DIJO QUE VENDRÍA OTRA VEZ', '/Cristo me dijo que vendría otra ...', '--', '[{"paragraph": "/Cristo me dijo que vendría otra vez, que vendría otra vez, que vendría otra vez/"}, {"paragraph": "/Alábale, alábale, alábale de corazón/ \n Yo le estoy, yo le estoy esperando \n Yo le estoy, yo le estoy esperando"}]'::jsonb, '[]'::jsonb, 'CRISTO ME DIJO QUE VENDRÍA OTRA VEZ.json'),
('a87413a1-c0c4-e91e-f290-64d1474265ea', 'DESDE QUE TE CONOCÍ', 'Desde que te conocí, desde que viniste a mi Desd', 'D|Re', '[{"id": "0c27cbea-0878-f773-2e87-208f1dba420c", "paragraph": "Desde que te conocí, desde que viniste a mi\nDesde que experimente, tu perdón, tu amor, tu paz.\nAlgo nuevo en mi empezó por tu espíritu de amor.\nEs tu vida cual semilla que brotó en mi corazón.", "chorusPos": [[0]]}, {"id": "4ab0bf36-6381-b734-f632-c8528e56d95c", "paragraph": "¡Qué momento tan feliz!\nQue alegría recibí;\nal tener en mi vida tu presencia celestial.\nSé de dónde vengo sé a dónde voy,\nsé quién soy, porque existo y tu propósito en mí.", "chorusPos": [[1]]}, {"id": "898f1125-9095-9aa3-24c1-01cbe20570d3", "paragraph": "Ahora que vives en mí,\nahora que te puedo oír,\nahora que crece en mí;\ntu persona sin igual\nQuiero dejar que seas tú para que no sea yo;\nEl que manda al que vean pues en mi a ti han de ver.", "chorusPos": [[0]]}, {"id": "93fd7ea7-ff60-01dc-2bb1-14884e8fa895", "paragraph": "Correré hasta alcanzar,\nla corona que darás\nEn el día que regreses y nos lleves al hogar,\nAllí llanto no habrá, la justicia reinará\nDesde el trono santo y justo reinaras.", "chorusPos": [[1]]}]'::jsonb, '[{"choir": "Quiero amar Oh Cristo,\nquiero dar Oh Cristo,\nquiero ser Oh Cristo como tu\nAl caído levantar al enfermo consolar\nA este mundo que agoniza tu remedio alcanzar", "id": "e2d0c003-e796-06ef-4870-3293f3cc6551"}]'::jsonb, 'DESDE QUE TE CONOCÍ.json'),
('79ff68f9-a1b2-4d02-b4fa-40cf78bbfc37', 'Cuando venga de los cielos el señor ', 'CUANDO VENGA DE LOS CIELOS EL SEÑ...', '--', '[{"paragraph": "CUANDO VENGA DE LOS CIELOS EL SEÑOR ESTÉS VIVO O ESTE MUERTO \n QUE CUENTA LE VAS A DAR"}, {"paragraph": "AMIGO YA NO PEQUES MAS \n  JESÚS TE DICE VEN A MI RECUERDA QUE ES TU SALVADOR RECUERDA QUE EL MURIÓ POR TI"}, {"paragraph": "OH VIENEN LOS ÁNGELES  \n VIENEN LOS ÁNGELES \n A ALABAR AL REY"}]'::jsonb, '[]'::jsonb, 'Cuando venga de los cielos el señor .json'),
('bb02cd79-874f-a8f9-5523-5e8489470fad', 'EL MISMO AMOR', 'Tú al humilde levantaras, Al débil tu fuerzas le', 'A|La', '[{"id": "4fe2442f-7f6c-d365-df5b-cb0307c0e27f", "paragraph": "Tú al humilde levantaras,\nAl débil tu fuerzas le das.\nNuestras heridas sanaras,\nVida nos das.", "chorusPos": [[1]]}, {"id": "00da77a0-7ff9-7b3e-e5fc-5a355a501617", "paragraph": "Al que o cree lo llamas tu,\nPara decirle mío eres tú.\nAl orgulloso llamas y al infeliz,\nVengan a mi.", "chorusPos": [[1], [2]]}, {"id": "ee6ece23-6953-e064-1859-db3f6f7d8edd", "paragraph": "//Nos llamas, nos llamas, nos llamas\nhacia Cruz//.", "chorusPos": [[1], [2]]}, {"id": "e57dbf22-124e-55ca-029f-f8080b009d30", "paragraph": "//Nos llamas, nos llamas, nos llamas\nhacia Cruz//.", "chorusPos": [[0]]}]'::jsonb, '[{"choir": "El mismo que trae libertad.\nEl mismo amor que al ciego vista da.\nNos llamas con nombre hoy.\nTu nos llamas por nombre hoy.\n\nEl mismo Dios que los cielos formo.\nEl mismo Dios que en la cruz murió.\nNos llama con nombre hoy.\nTu nos llamas por nombre hoy.", "id": "e47f3bae-b9c2-219c-5574-c5a18e5a1593"}, {"choir": "//Oohh….. Oohh… oohh…//", "id": "dc17c1ae-f11e-0559-cd71-15ffa6c38e47"}]'::jsonb, 'EL MISMO AMOR.json'),
('e8baa8a5-6dca-6678-6170-a0c6e6fe7dbf', 'Salmos 19 - La Ley de Jehova', 'La ley de Jehová es perfecta,         que convie', 'C|Do', '[{"id": "37af71ea-9f96-fa70-c851-43d744e8d909", "paragraph": "La ley de Jehová es perfecta,\n        que convierte el alma;\n        El testimonio de Jehová es fiel,\n        que hace sabio al sencillo.", "chorusPos": [[1]]}, {"id": "ab6a1f53-a7d8-28b7-b0c6-71a8402fd0b9", "paragraph": "Los mandamientos de Jehová son rectos,\n        que alegran el corazón;\n        El precepto de Jehová es puro,\n        que alumbra los ojos.", "chorusPos": [[1]]}, {"id": "8c8b92be-2295-34db-fc09-2f571d62a507", "paragraph": "El temor de Jehová es limpio,\n        que permanece para siempre;\n        Los juicios de Jehová son verdad,\n        todos justos.", "chorusPos": [[1]]}]'::jsonb, '[{"choir": "Deseables son más que el oro,\n        y más que mucho oro afinado;\n        y dulces más que la miel,\n        la que destila del panal.", "id": "85d944f8-64f6-6f05-b892-50ae33e12509"}]'::jsonb, 'Salmos 19 - La Ley de Jehova.json'),
('59ae71c2-f07d-3c55-dd52-155d78aeb31f', 'SUBLIME GRACIA', 'Sublime gracia del Señor que aun infeliz salvo. ', 'C|Do', '[{"id": "2803797f-f4bf-3343-6308-3cb9c9432bbc", "paragraph": "Sublime gracia del Señor que aun infeliz salvo.\nFui ciego mas hoy veo yo,\nPerdido y Él me hallo.", "chorusPos": [[0]]}, {"id": "9e1b0f00-76c9-d78a-3855-ca70ed9e43c8", "paragraph": "Su gracia me enseñó a temer,\nmis dudas ahuyento.\nOhh cuan precioso fue a mis ser,\nCuando él me transformo.", "chorusPos": [[1]]}, {"id": "d2375c32-d858-cd60-5da9-093701dae493", "paragraph": "En los peligros o aflicción,\nque yo he tenido aquí.\nSu gracia siempre me libro,\nY me guiara feliz.", "chorusPos": [[1]]}, {"id": "8404208d-cb78-ec72-2277-2d6a85d6bfcb", "paragraph": "Y cuando en Sion por siglos mil,\nBrillante este cual sol.\nY aun cantare por siempre aquí\nSu amor que me salvo.", "chorusPos": [[2]]}]'::jsonb, '[{"choir": "Ya libre soy Dios me salvo,\n        Y mis cadenas ya Él rompió\n        Y como un rio fluye el perdón\n        Sublime gracia inmenso amor.", "id": "4e1b8d53-f144-62cd-4a6e-844442c7f8eb"}, {"choir": "/Ya libre soy Dios me salvo,\n          Y mis cadenas ya Él rompió\n          Y como un rio fluye el perdón\n          Sublime gracia inmenso amor./", "id": "ac490b0f-cad6-071b-9022-567aa7eb1e68"}]'::jsonb, 'SUBLIME GRACIA.json'),
('17783967-a675-4ec9-9584-e9199c5e3858', 'En Jesus me Esconderé', 'Al abrigo del Señor Altísimo,   h...', '--', '[{"paragraph": "Al abrigo del Señor Altísimo, \n habitaré, \n A la sombra del omnipotente Rey,  \n descansaré."}, {"paragraph": "Si la enfermedad acecha,  \n si hay plaga por doquier. \n Firme en Sus promesas estaré, \n en Jesús me esconderé."}, {"paragraph": "En Ti confío Dios,  \n poderoso Emanuel. \n En Ti está mi fe,  \n en Jesús me esconderé."}, {"paragraph": "A la voz del Salvador  \n Sus ángeles, me cuidarán.  \n Con Su mano soberana  \n al tropezar, me sostendrá."}, {"paragraph": "En Sus alas de refugio \n mis temores rendiré. \n Me rodea Su fidelidad,  \n en Jesús me esconderé."}, {"paragraph": "En Ti confío Dios,  \n poderoso Emanuel. \n En Ti está mi fe,  \n en Jesús me esconderé."}, {"paragraph": "Aunque miles caigan junto a mí \n y muerte pueda ver. \n La maldad no vencerá  \n mientras Jesús conmigo esté."}, {"paragraph": "/Porque Él ha resucitado,  \n el morir no temeré./ \n Mientras viva y por la eternidad, \n en Jesús me esconderé."}, {"paragraph": "/En Ti confío Dios,  \n poderoso Emanuel. \n En Ti está mi fe,  \n en Jesús me esconderé./"}]'::jsonb, '[]'::jsonb, 'En Jesus me Esconderé.json'),
('fe05a778-6506-2da7-631a-c1338c232fe8', 'SI TE TENGO', 'No hay nada para mí que sea mejor, Que conocerte', 'G|Sol', '[{"id": "488f1d7c-476b-a4e9-e9d8-11c51984b71c", "paragraph": "No hay nada para mí que sea mejor,\nQue conocerte, mi Jesús.\nPues en Tí encuentro paz´, Y el amor,\nQue me has dado en la cruz.\nPor eso yo quiero cantar.", "chorusPos": [[1]]}, {"id": "0028fca1-bba8-0159-c428-9124ead01a1d", "paragraph": "Puedo amarte por que Tú Me amaste a mí,\nSiendo yo un pecador.\nNo merecía Tu perdón Menos aún,\nSer llamado hijo de Dios.\nPor eso yo quiero cantar.", "chorusPos": [[1]]}]'::jsonb, '[{"choir": "Eres todo lo que anhelo,\nTu voluntad es lo que quiero.\nTú satisfaces mi vida entera,\nTú, mi porción y mi roca eterna.\nLo que yo tengo lo doy por perdido,\nSi te tengo a Ti.", "id": "251db946-ae87-aeff-0add-55a76c54647b"}]'::jsonb, 'SI TE TENGO.json'),
('7b3fbae3-a6dc-4a38-bff8-0cb44a63dc68', 'Amémonos hermanos de todo corazón una familia somos', 'Amémonos hermanos de todo corazón...', '--', '[{"paragraph": "Amémonos hermanos de todo corazón una familia somos en nuestro padre dios \n el señor Jesucristo nos ha dejado un mandamiento nuevo  \n primero es el amor \n amemonos…. \n Aunque vengan tempestade nada tamas hoy hermanod esfuersate  \n cuando venga jesucristo aus gloria NO llevara \n falta poco para y a la se \n nuestra lucah se termina \n con crsito en su morda ya no habra mas sufirmeitop"}]'::jsonb, '[]'::jsonb, 'Amémonos hermanos de todo corazón una familia somos.json'),
('d1d64942-aee2-4098-9b78-fada74220ba5', 'De la misma iglesia', 'De la misma   Iglesia tú eres    ...', '--', '[{"paragraph": "De la misma \n Iglesia tú eres  \n si detrás del \n  calvario tú estás"}, {"paragraph": "si tú corazón  \n es como el mío \n dame la mano y  \n mi hermano serás"}, {"paragraph": "/Dame la mano, \n Querido hermano \n dame la mano  \n  mi hermano serás/"}]'::jsonb, '[]'::jsonb, 'De la misma iglesia.json'),
('5f020110-0ba0-daaa-5f8b-f51b55672fa2', '10.000 RAZONES', '[C]Que todo lo que soy [F]alabe al Señor,   [G]c', 'C|Do', '[{"paragraph": "[C]Que todo lo que soy [F]alabe al Señor, \n [G]con todo mi [C]corazón. \n [F]De Tu grande [G]amor, cantaré [Em]\n [Am]Tu nombre alabaré [F]. [G]"}, {"paragraph": "[C]Sale el Sol, es un [F]nuevo amanecer, \n [G]cantaré a ti [C]otra vez. \n [F]Sea lo que [G]venga, confiaré [Em]en ti, \n [Am]alabaré en el [F]anochecer [G]."}, {"paragraph": "[C]Que todo lo que soy [F]alabe al Señor, \n [G]con todo mi [C]corazón. \n [F]De Tu grande [G]amor, cantaré, [Em]\n [Am]Tu nombre alabaré [F]. [G]"}, {"paragraph": "[C]Tu amor no tiene [F]fin y Tú eres [G]para siempre, \n [C]y bondadoso es [F]Tu corazón [G]. \n [Em]Por todo lo que [Am]has hecho, yo sigo [F]cantando, \n [C]10.000 razones [G]para alabar [C]."}, {"paragraph": "[C]Que todo lo que soy [F]alabe al Señor, \n [G]con todo mi [C]corazón. \n [F]De Tu grande [G]amor, cantaré [Em]\n [Am]Tu nombre alabaré [F]. [G]"}, {"paragraph": "[Am]Y en ese día, cuando [F]ya no tenga [G]fuerza, \n [Em]y se acerque Tu [Am]gloria. \n [F]Mi alma cantará [G]de tu amor sin [Em]final, \n [Am]10.000 años y [F]para siempre [G]más [C]."}, {"paragraph": "[C]Que todo lo que soy [F]alabe al Señor, \n [G]con todo mi [C]corazón. \n [F]De Tu grande [G]amor, cantaré \n [Am]/Tu nombre alabaré./ [F][G][C]"}]'::jsonb, '[]'::jsonb, '10.000 Razones.json'),
('947fcfc6-d732-fa7a-9e0c-026c9f8558a3', 'CONTEMPLA A DIOS', '¿Quién formó las olas al hablar?, ¿Quién contó l', 'C|Do', '[{"id": "28a32dea-1203-984f-7446-8d5b642568ac", "paragraph": "¿Quién formó las olas al hablar?,\n¿Quién contó la arena en el mar?\nReyes, pueblos, tiemblan a su voz,\nla creación le rinde adoración.", "chorusPos": [[2]]}, {"id": "3eb8453e-5e2f-6e88-4d95-32bd1a42469c", "paragraph": "¿Quién le dio consejo al Señor?,\n¿Quién cuestiona lo que Él habló?\nQuién al sabio Dios puede enseñar,\n¿Quién comprende su gran majestad?", "chorusPos": [[2]]}, {"id": "92ad8b90-3ed9-4d52-6087-75a69475312d", "paragraph": "¿Quién sufrió los clavos en dolor?\n¿Quién llevo el mal del pecador?\nJesucristo, humilde al perecer,\nHa triunfado y reina con poder.", "chorusPos": [[2]]}, {"id": "0e7856ee-23c5-0c10-01bc-b409b9a9c96f", "paragraph": "", "chorusPos": [[1], [2]]}]'::jsonb, '[{"choir": "//¡Reinaras por siempre!//\n//¡Que tu gloria brille hoy!//", "id": "366284fd-9fb2-92c8-acc8-ddafa728b212"}, {"choir": "Contempla a Dios, en su trono está venid y adoradle.\nContempla al Rey, nadie es como Él venid y adoradle.", "id": "d99a0ab5-8c18-9106-af1e-d0b8b90ad2cb"}]'::jsonb, 'Contempla a Dios.json'),
('c1656a97-eccd-f3f4-f4c0-58a5d58c18cc', 'GLORIFICATE', 'Que toda nación te adore, Que toda la tierra cla', '_', '[{"id": "107e63ee-8cbb-f190-4f3f-dda08da9bcad", "paragraph": "Que toda nación te adore,\nQue toda la tierra clame a ti.\nQue todos tus santos canten;\n¡Santo es el Señor!", "chorusPos": [[0]]}, {"id": "7378098b-13ea-54a8-2571-ad647b7f875a", "paragraph": "Declaramos tu grandeza,\nlos cielos cuentan Tu gloria Dios\ny tus redimidos cantan\n¡Santo!, ¡Santo!", "chorusPos": [[1]]}, {"id": "ae40d2af-d0a5-624b-b2e0-a80f64a1c889", "paragraph": "Que toda nación te adore,\nQue toda la tierra clame a ti.\nQue todos tus santos canten;\n¡Santo es el Señor!", "chorusPos": [[0]]}, {"id": "90818fc3-84a9-6fb7-bc99-2c566d70dba5", "paragraph": "Declaramos tu grandeza,\nLos cielos cuentan tu gloria oh Dios\ny tus redimidos cantan\n¡Santo!, ¡Santo", "chorusPos": [[2]]}, {"id": "d32f3376-f45f-1a4b-c847-511fe59b4000", "paragraph": "/¡Aleluya! te damos gloria vivimos para ti./", "chorusPos": [[3]]}]'::jsonb, '[{"choir": "Al cantar abre los cielos\nY haz llover, muestra tu gloria,\nTe queremos ver\nY al adorarte, exáltate\nGlorifícate.", "id": "f5bea8f4-52b6-dfb0-20be-999be6f9215c"}, {"choir": "Al cantar abre los cielos\nY haz llover, muestra tu gloria,\nTe queremos ver\nY al adorarte, exáltate\n/Glorifícate/", "id": "6702afc2-03ba-cd7a-caf7-e87b099788ad"}, {"choir": "//Glorifícate\nAbre los cielos\nY haz llover,\nMuestra tu gloria\nTe queremos ver\nY al adorarte, exáltate//\n\n//Glorifícate//", "id": "400c701b-0669-59a9-8432-9c24702f508b"}]'::jsonb, 'GLORIFICATE.json'),
('88f9c41e-6a62-45f9-a4ca-5b6bfa650a91', 'Eres tu la única razón de mi adoración', 'ERES TU LA ÚNICA RAZÓN DE MI ADOR...', '--', '[{"paragraph": "ERES TU LA ÚNICA RAZÓN DE MI ADORACIÓN OH JESÚS  \n ERES TU LA ESPERANZA QUE ANHELE TENER OH JESÚS"}, {"paragraph": "CONFIE EN TI Y ME HAS AYUDADO \n TU SALVACION ME HAS REGALADO \n HOY HAY GOZO EN MI CORAZON  \n CON MI CANTO TE ALABARE"}, {"paragraph": "/TE ALABARE, TE GLORIFICARE \n TE ALABARE MI BUEN JESUS/ \n EN TODO TIEMPO  \n TE ALABARE  \n EN TODO TIEMPO  \n TE ADORARE  \n \t\t\t//TE ALABARE//"}]'::jsonb, '[]'::jsonb, 'Eres tu la única razón de mi adoración.json'),
('6c4d3d5c-5472-11f5-f8e3-0a50e997443c', 'ÈL ES CRISTO', 'Quién ayuda al herido Sana todo dolor Permanece ', '_', '[{"id": "8d00ea1d-8711-fe71-2333-b6bc0eca95cc", "paragraph": "Quién ayuda al herido\nSana todo dolor\nPermanece por siempre\nDa descanso en su amor\nÉl es cristo.\nÉl es cristo\nNuestro salvador.\nÉl es cristo\nNo hay otro nombre solo Cristo", "chorusPos": [[0]]}, {"id": "3ecb0f83-32f0-11f0-e70f-1a718290364f", "paragraph": "Quién llevó nuestras cargas\nCambia el llanto en canción\nDio su vida en la cruz\nPara darnos perdón\nÉl es cristo\nÉl es cristo\nNuestro salvador\nÉl es cristo\nÉl es cristo\nRey por siempre\nNuestro redentor", "chorusPos": [[0]]}, {"id": "884b50e9-76b1-972a-947f-e197e2938a7a", "paragraph": "Él es cristo\nQuién moriría por un ladrón\nY tomaría mi lugar\nTodo el precio pago\n// Libres somos el venció //\nEl venció Libre somos\n\n//// No hay otro nombre solo cristo\nNo hay otra vida vivimos por él\nTodo el mal está vencido\n/ Tu reinas señor / ////\n\n/ Él es cristo /\nNuestro salvador\n/ Él es cristo /\nRey por siempre\nNuestro redentor\nÉl es cristo", "chorusPos": [[0]]}]'::jsonb, '[]'::jsonb, 'ÈL ES CRISTO.json'),
('6c45f6eb-daf5-4c6c-9cae-4dee62067c1e', 'HASTA LOS RIOS ALABAN TU NOMGRE', '//Hasta los ríos alaban Tú nombre...', '--', '[{"paragraph": "//Hasta los ríos alaban Tú nombre// \n Mi bendito Cristo \n //Asi lo mismo quiero alabarte//"}, {"paragraph": "Quiero alabarte con estas mis manos \n Quiero alabarte con este mi cuerpo \n Mi bendito Criso"}]'::jsonb, '[]'::jsonb, 'HASTA LOS RIOS ALABAN TU NOMGRE.json'),
('bc65fcf0-60cb-4d75-8765-da21c9744af8', 'EL HOMBRE DE GALILEA', 'GALILEA    VA PASANDO YA//   //DE...', '--', '[{"paragraph": "GALILEA  \n VA PASANDO YA// \n //DEJALO QUE TE TOQUE// \n  Y TE DE SU BENDICION"}, {"paragraph": "//EL HOMBRE DE"}, {"paragraph": "GALILEA  \n VA PASANDO AQUI// \n //DEJALO QUE TE TOQUE// \n  Y TE DE SU BENDICION"}]'::jsonb, '[]'::jsonb, 'EL HOMBRE DE GALILEA.json'),
('15a9ab4e-7572-bad3-4db2-210aca8d3c05', 'ANTE EL TRONO CELESTIAL', 'Ante el trono celestial Él intercede hoy por mí ', 'C/D|Do-Re', '[{"id": "c523100f-be39-be89-415b-ea33f3adcc6f", "paragraph": "Ante el trono celestial\nÉl intercede hoy por mí\nGran Sacerdote es Jesús\nQuien por siempre vivirá", "chorusPos": [[1]]}, {"id": "61dfe5b1-a86c-60e4-d42c-d0e07b6129d0", "paragraph": "Cuando he caído en tentación\nY al sentir condenación\nAl ver al cielo encontraré\nAl inocente quien murió.", "chorusPos": [[2]]}, {"id": "02dc7fd4-e32e-d20f-5e86-bf82abce9408", "paragraph": "Ante el Cordero Redentor\nQuién al morir resucitó\nEl inmutable gran Yo Soy\nEl Rey de gloria y majestad", "chorusPos": [[3]]}]'::jsonb, '[{"choir": "Y en Sus manos por Su amor\nMi nombre ya grabado está\nY mientras en el cielo esté\n/ Nadie de Él me apartará /", "id": "32e31207-bd59-e62d-9665-d249cfaf0063"}, {"choir": "Y por su muerte el Salvador\nYa mi pecado perdonó\nPues Dios, el Justo, aceptó\n/ Su sacrificio hecho por mí /", "id": "62f1cc91-2ad2-b73e-aa96-b7671cb1de43"}, {"choir": "/ Unido a Él no moriré\nPues con Su sangre me compró\nMi vida escondida está\nEn Cristo Dios, mi Salvador/\n\n/En Cristo Dios, mi Salvador/", "id": "400f9e28-1fbf-d2e7-fb40-3b76a3dd147d"}]'::jsonb, 'ANTE EL TRONO CELESTIAL.json'),
('0a04e4a0-76bd-4a1d-9462-330c27c2a054', 'CANTA AL SENOR', 'CANTA  AL SENOR   M Cristo m rey ...', '--', '[{"paragraph": "CANTA  AL SENOR \n M Cristo m rey  \n No hay nade como tu \n Toda m vida quiero exaltar \n Las maravillas de tu amor"}, {"paragraph": "Consuelo, refugio  torre de fuerza y poder \n Todo m ser , lo que yo soy \n Nunca cese de adorar"}, {"paragraph": "Canta al señor, la creación  cantare \n La majestad y el poder sean a el \n Montes caerán  y el mar crujirá al sonar de tu nombre."}, {"paragraph": "Canto con gozo al mirar tu poder \n Siempre yo te amare y diré  \n incomparables promesa yo tengo en t"}]'::jsonb, '[]'::jsonb, 'CANTA AL SENOR.json'),
('68e4ad5c-50e5-4d56-9306-504cfc450f6f', 'COMO LAS ÁGUILAS', 'TU ME DAS LA FUERZA O DIOS    CAM...', '--', '[{"paragraph": "TU ME DAS LA FUERZA O DIOS  \n CAMINARE POR TI Y NO ME FATIGARE"}, {"paragraph": "AHORA QUE SOY JOVEN YO QUIERO BUSCARTE DE CORAZÓN  \n LO QUE ME OFRECE EL MUNDO NO QUIERO  \n ME DECLARO LIBRE, LIBRE PARA TI SEÑOR"}]'::jsonb, '[]'::jsonb, 'COMO LAS ÁGUILAS.json'),
('3da09f4a-8aa6-4b59-b992-321bc8881c71', 'DIOS DE MARAVILLAS', 'Todo lo creaste, la tierra cielo ...', '--', '[{"paragraph": "Todo lo creaste, la tierra cielo y mar. \n Los cielos son tu tabernáculo, Gloria al Dios altísimo."}, {"paragraph": "Dios del cielo maravilloso Dios, eres Santo, Santo. \n La creación muestra su majestad, eres Santo, Santo. \n //Dios de la creación. //"}, {"paragraph": "Cuando amanezco, he de celebrar tu luz. \n Si tropiezo en tinieblas, volveré a ver tu Cruz. \n //Dios del cielo maravilloso Dios, eres Santo, Santo. \n La creación muestra su majestad, eres Santo, Santo//"}, {"paragraph": "//Dios de la creación.// ALELUYA \n //Al Dios de la creación//"}, {"paragraph": "Dios del cielo maravilloso Dios, eres Santo, Santo. \n Muéstrame Señor tu corazón, eres Santo, Santo, Santo. \n //Dios de la creación. // ALELUYA. \n //Al Dios de la creación//"}]'::jsonb, '[]'::jsonb, 'DIOS DE MARAVILLAS.json'),
('d2e65938-1ea0-637d-f37e-ab83e0864274', 'YAHWEH', 'Con tu palabra el mundo afirmaste Señor. Tú alie', '_', '[{"id": "af3ffba5-526e-d52d-4ae9-bcb1121e5e32", "paragraph": "Con tu palabra el mundo afirmaste Señor.\nTú aliento de vida;\ndel polvo la humanidad formó.\nDespliegas tu nombre, y gloria en toda la creación.\nSANTO DIOS, SANTO DIOS.\n\nAun cuando el pecado, tu creación corrompió.\nEn tú fidelidad nos prometiste redención.\nun plan soberano por gracia y justicia mostró\nSANTO DIOS, SANTO DIOS\n\nSiempre guardas tus palabras, siempre\ncumples tus promesas.\nPor amor de tu nombre; Santo nombre.", "chorusPos": [[1]]}, {"id": "943c1bcd-32a0-0775-19e2-d70b7bc896d7", "paragraph": "En tiempo preciso el verbo carne se hizo.\nA que por bien esperamos,\nEl prometido en el principio.\nY vimos tu rostro llena de gracia y verdad.\nEn Jesús hijo de Dios SANTO DIOS.", "chorusPos": [[1]]}, {"id": "48f2a351-4368-c457-999b-032b106c76ef", "paragraph": "Nos aferramos a tus palabras,\nY creemos en tus promesas,\nY adoramos hoy tu nombre;\nSANTO NOMBRE.", "chorusPos": [[1], [2]]}]'::jsonb, '[{"choir": "YAHWEH, YAHWEH.\nPoderoso, Dios eterno ,verdadero.\n¿Ohh quién es como tú?\n\nYAHWEH, YAHWEH.\nTú nombre permanecerá para siempre\nOhhh YAHWEH", "id": "85fbe665-87b2-0c64-c00a-c23f83e533c1"}, {"choir": "YAHWEH ES TU NOMBRE :YAHWEH.\nOhhh ¡YAHWEH!", "id": "4be8c61b-d567-5b29-74be-262bfd6b1a23"}]'::jsonb, 'YAHWEH.json'),
('1f8f344e-538d-46ae-a621-3bfb72068f77', 'dame esos montes', 'Que a vivado mis sueños y mis van...', '--', '[{"paragraph": "Que a vivado mis sueños y mis vanidades las deje  \n dame esos montes y con mis fuerzas las hare cumplire la promesa yo e sido creado que  \n no habra gigante que me haga dudar \n y mi bandera eh de alzar \n hay quienes aconsejan que toque  ahora la retirada que lo aque se ahze en joven el viejo"}, {"paragraph": "que ya no digas"}]'::jsonb, '[]'::jsonb, 'dame esos montes.json'),
('708f5dca-ac43-49fc-be98-3790e8568125', 'Gracia más Grande', 'Hay una fuente que lava toda iniq...', '--', '[{"paragraph": "Hay una fuente que lava toda iniquidad, \n de sus heridas fluye el más dulce manantial; \n Quita mi culpa, perdona toda mi maldad \n ¡Aleluya!"}, {"paragraph": "Misericordia encuentra el más vil pecador, \n en el Calvario donde sangró mi Salvador; \n Río de gracia, que inundó mi corazón, \n ¡Aleluya!"}, {"paragraph": "Cristo, Tu sangre me hace más que vencedor, \n ¿Quién podrá separarme? \n Cristo, Tu nombre es mi refugio y salvación, \n Poderoso."}, {"paragraph": "Hay una fuente que borra todo mi temor, \n y mi vergüenza la cubre con su perfección; \n Allí el sediento se llena y sacia de favor, \n ¡Aleluya!"}, {"paragraph": "Cristo, Tu sangre me hace más que vencedor, \n ¿Quién podrá separarme? \n Cristo, Tu nombre es mi refugio y salvación, \n Poderoso."}, {"paragraph": "/Gracia más grande que el pecado, \n con un poder más fuerte mi alma ha rescatado; \n ¿Cómo no he de darte mi alabanza? \n Mi corazón te canta Tu nombre sea exaltado./"}, {"paragraph": "Cristo, Tu sangre me hace más que vencedor, \n ¿Quién podrá separarme? \n Cristo, Tu nombre es mi refugio y salvación, \n Poderoso."}]'::jsonb, '[]'::jsonb, 'Gracia más Grande.json'),
('6d99a9f7-c033-47df-ad15-7ec648f57f39', 'CON CRISTO HAY ALEGRIA LO PUEDES TU PROBAR', 'CON CRISTO HAY ALEGRIA LO PUEDES ...', '--', '[{"paragraph": "CON CRISTO HAY ALEGRIA LO PUEDES TU PROBAR \n ENTREGALE TU VIDA"}, {"paragraph": "YA NO TIENES QUE SUFRIR YA NO TIENES QUE LLORAR EL VINO PARA DARTE PAZ Y FELICIDAD"}]'::jsonb, '[]'::jsonb, 'CON CRISTO HAY ALEGRIA LO PUEDES TU PROBAR.json'),
('13f0ca89-653c-129a-ccf6-5f3710800857', 'TÚ ERES MI RESPIRAR', '//Tú eres mi respirar// Dios tu presencia vive e', '_', '[{"id": "fd53ee9b-70ce-7153-9a2d-d56c2b3343d4", "paragraph": "//Tú eres mi respirar//\nDios tu presencia vive en mi.\n\n//Tú eres mi pan Señor//\nDios tus palabras son para mi.", "chorusPos": [[1]]}]'::jsonb, '[{"choir": "Y yo……..\nte anhelo Señor…..\nEstoy….\nPerdido sin ti….", "id": "93a38a07-6e16-9fa6-1170-2ca3b13a3155"}]'::jsonb, 'TÚ ERES MI RESPIRAR.json'),
('dacf4258-b9da-42be-a5e8-87cc92999b47', 'Amante Salvador 105', 'Amante Salvador, dame tu gran pod...', '--', '[{"paragraph": "Amante Salvador, dame tu gran poder \n Para testificar de tu infinito amor"}, {"paragraph": "/Cristo, mi Salvador, \n Me has perdonado del mal. \n De todo corazón te seguiré con fe/"}, {"paragraph": "Con gozo y paz iré al cielo, oh Señor, \n Pues con tu gran amor, siempre me guiarás."}, {"paragraph": "/Cristo, mi Salvador, \n Me has perdonado del mal. \n De todo corazón te seguiré con fe/"}, {"paragraph": "Tus nuevos cánticos enséñame, Señor, \n Para alabarte más de todo corazón."}, {"paragraph": "/Cristo, mi Salvador, \n Me has perdonado del mal. \n De todo corazón te seguiré con fe/"}, {"paragraph": "Tu, Santo Espíritu, manda a mi corazón. \n Él me consolará, y me dará su paz."}, {"paragraph": "/Cristo, mi Salvador, \n Me has perdonado del mal. \n De todo corazón te seguiré con fe/"}]'::jsonb, '[]'::jsonb, 'Amante Salvador 105.json'),
('44012183-27ed-4f4e-abd4-40a1b30ff412', 'EL GOZO QUE TENGO YO', '/El gozo que tengo yo,   el mundo...', '--', '[{"paragraph": "/El gozo que tengo yo, \n el mundo no me lo dio,  \n el mundo no me lo dio \n /como no me lo dio, \n no me lo puede quitar//"}, {"paragraph": "si empezamos a cantar, \n esta tierra tiembla \n si empezamos a orar  \n hablaremos nuevas lenguas"}, {"paragraph": "/Elías oró el fuego cayó \n oró Josué el sol se paro/ \n /Este gozo  \n que yo siento en mi alma \n solo Cristo me lo pudo dar/"}, {"paragraph": "/solo Cristo me lo pudo dar/ \n Este gozo  \n que yo siento en mi alma \n solo Cristo me lo pudo dar"}, {"paragraph": "//pero que felicidad/  \n cantando todos en coro \n a nuestro Padre celestial/"}, {"paragraph": "/Yo no sé a que tu has venido, \n Pero yo vine alabar a DIOS/ \n /yo vine, yo vine, \n yo vine alabar a DIOS/"}]'::jsonb, '[]'::jsonb, 'EL GOZO QUE TENGO YO.json'),
('07a3a5d8-cc61-4e8b-91ab-2cbcca530983', 'En la santa palabra del señor', 'En la santa palabra del señor    ...', '--', '[{"paragraph": "En la santa palabra del señor  \n no habra necesidad de la luz en su amor el señor dara su luz y alliu llanto no habra ni trizyeza NI dolor"}, {"paragraph": "por que enstonces jesus el rey del cielo para siempre sera consolador"}]'::jsonb, '[]'::jsonb, 'En la santa palabra del señor.json'),
('24b7b952-01c6-4606-bb80-aaed15f94941', 'HAY VICTORIA', '/HAY VICTORIA/ HAY VICTORIA EN LA...', '--', '[{"paragraph": "/HAY VICTORIA/ HAY VICTORIA EN LA SANGRE DE JESÚS \n NO PODRÁ EL ENEMIGO VENCER  A NUESTRAS ALMAS  \n POR QUE YO SE QUE HAY VICTORIA  \n  HAY VICTORIA EN LA SANGRE DE JESÚS."}, {"paragraph": "SI ME PREGUTAN POR QUE ESTOY CONTENTO  \n SI ME PREGUNTAN POR QUE CANTO ASI  \n ES POR QUE CRISTO ME A LAVADO CON SU SANGRE  \n Y EN UNA NUBE BLANCA VOLVERA POR MI"}]'::jsonb, '[]'::jsonb, 'HAY VICTORIA.json'),
('41515899-c220-4e3d-ab0e-74a2a69f0139', 'HEME AQUI YO IRE SEÑOR', 'Heme aquí, yo iré Señor   Heme aq...', '--', '[{"paragraph": "Heme aquí, yo iré Señor \n Heme aquí, yo iré Señor"}, {"paragraph": "Envíame a mi; que dispuesto estoy, \n  llevaré tu gloria a las naciones"}]'::jsonb, '[]'::jsonb, 'HEME AQUI YO IRE SEÑOR.json'),
('2dd1f945-5017-44ac-a124-0ddbf741bce7', 'Es para ti que canto', 'Es para ti que canto   Es para ti...', '--', '[{"paragraph": "Es para ti que canto \n Es para ti que salto con los pies con las mano es así que yo te alabo \n para arriba para abajo ooooo"}, {"paragraph": "///Celebrad a cristo celebrad///  \n /Resucito/ \n Y el vive para siempre  \n  /Resucito/  \n Vamos a celebrar uh \n Vamos a celebrar Cristo! \n vamos a celebrar Resucito el señor"}]'::jsonb, '[]'::jsonb, 'Es para ti que canto.json'),
('e029d2f3-fbac-cb20-1996-7d5a06a886e8', 'MARCHEMOS A LA UNIDAD', 'Yo sé que fue pagado un alto precio, Para que se', 'G|Sol', '[{"id": "b26b8eb6-95f1-6186-dfce-9d562ac4ba6b", "paragraph": "Yo sé que fue pagado un alto precio,\nPara que seamos uno tu y yo.\nCuando Jesús derramaba su vida,\nÉl pensaba en ti, Él pensaba en mi\nEn nuestra unidad.", "chorusPos": [[0]]}, {"id": "98c81f96-9b7a-0306-daee-122a202e9409", "paragraph": "Nos veía redimidos por su sangre\nCombatiendo la batalla de la fé\nCodo a codo trabajando\nSu iglesia edificando\nY rompiendo las cadenas por amor.", "chorusPos": [[1]]}]'::jsonb, '[{"choir": "//Y mediante el Espíritu Santo\nProclamamos hoy aquí.\nQue pagaremos el precio de ser\nTodos un corazón en Jesús.\n\nY si las tinieblas militan\nY nos quieran separar\nCon nuestros ojos en Cristo\nMarchemos a la unidad//.", "id": "9dbf9cb8-ac40-81ea-1b2e-de5ee6d94b8f"}]'::jsonb, 'MARCHEMOS A LA UNIDAD.json'),
('a1bdb252-2af1-4832-bee0-85c23f42a99e', 'A QUIEN IRE', 'A quien iré en necesidad   A quie...', '--', '[{"paragraph": "A quien iré en necesidad \n A quien iré en busca de paz \n Y quien podrá  \n mi vida saciar de verdad."}, {"paragraph": "Quién más tendrá  \n de mi compasión \n Y entenderá mi corazón \n Quien cambiara  \n mi eternidad si no Tú Jesús."}, {"paragraph": "/Cristo, a dónde más podría ir, \n Cristo, que otro lugar \n  puede existir, \n Solo Tú tienes  \n palabras de amor, \n Camino al Padre \n  y verdad eres Tú/."}]'::jsonb, '[]'::jsonb, 'A QUIEN IRE.json'),
('e8baa8a5-6dca-6678-6170-a0c6e6fe7dbf', 'Salmos 19 - La Ley de Jehova', 'La ley de Jehová es perfecta,         que convie', 'C|Do', '[{"id": "37af71ea-9f96-fa70-c851-43d744e8d909", "paragraph": "La ley de Jehová es perfecta,\n        que convierte el alma;\n        El testimonio de Jehová es fiel,\n        que hace sabio al sencillo.", "chorusPos": [[1]]}, {"id": "ab6a1f53-a7d8-28b7-b0c6-71a8402fd0b9", "paragraph": "Los mandamientos de Jehová son rectos,\n        que alegran el corazón;\n        El precepto de Jehová es puro,\n        que alumbra los ojos.", "chorusPos": [[1]]}, {"id": "8c8b92be-2295-34db-fc09-2f571d62a507", "paragraph": "El temor de Jehová es limpio,\n        que permanece para siempre;\n        Los juicios de Jehová son verdad,\n        todos justos.", "chorusPos": [[1]]}]'::jsonb, '[{"choir": "Deseables son más que el oro,\n        y más que mucho oro afinado;\n        y dulces más que la miel,\n        la que destila del panal.", "id": "85d944f8-64f6-6f05-b892-50ae33e12509"}]'::jsonb, 'Salmos - La Ley de Jehova.json'),
('fa938d97-7ec6-409f-85fe-62512581459c', 'AUNQUE NO ENCUENTRE UNA PUERTA', 'AUNQUE NO ENCUENTRE UNA PUERTA   ...', '--', '[{"paragraph": "AUNQUE NO ENCUENTRE UNA PUERTA  \n AUNQUE NO ENCUENTRE UNA SALIDA  \n EN TI DESCANSA MI ESPIRITU \n EN TI DESCANSA MI ALMA"}, {"paragraph": "SE MI PUERTA Y MI SALIDA  \n EN TODO TIEMPO SE MI SOSTEN  \n A QUIEN TENGO YO SI NO A TI  \n OH… JESUS"}]'::jsonb, '[]'::jsonb, 'AUNQUE NO ENCUENTRE UNA PUERTA.json'),
('f7b915d3-77d8-6189-07d0-743dc2ea3810', 'TE DOY GRACIAS', 'Cuando sale el sol temprano cada día Es tu graci', 'D|Re', '[{"id": "6ab57ae2-689d-af4e-ab07-15a498b40851", "paragraph": "Cuando sale el sol temprano cada día\nEs tu gracia que me da aliento de vida\nEn ti vivimos, nos movemos y existimos\nPor orden de tu voz.", "chorusPos": [[0]]}, {"id": "676a751a-eb33-204c-b5fb-44abda6d608f", "paragraph": "Tu presencia me refresca en la mañana\nMe alimenta y me sustenta tu Palabra\nTu favor y bien rodean mi camino\nPor tu constante amor.", "chorusPos": [[1], [2]]}, {"id": "c3df5e23-d7ec-e6d9-8f9b-0ce7d64c3356", "paragraph": "Al oscurecer, cuando llega la noche\nTú me libras de ansiedades y temores\nEs tu mano mi refugio y mi descanso\nEres mi guardador", "chorusPos": [[3]]}, {"id": "32f25e61-889e-59ae-891b-d2195bf79252", "paragraph": "Padre, ¿Cómo he de dudar de tus bondades?\nSi a tu Hijo unigénito entregaste\nMe has llamado por mi nombre y me salvaste\nAgradecido estoy", "chorusPos": [[0]]}]'::jsonb, '[{"choir": "Te doy gracias\nGrandes son tus obras,\nOh mi Dios\nTe doy gracias\nPor tu fidelidad, bondad y amor\nTe doy gracias\nMi alma te bendice hoy", "id": "7773614a-e271-daac-024e-1b39b5f3d055"}, {"choir": "Tu demuestras que me amas y me cuidas\nY me suples siempre\nel pan de cada día\nNada bueno tú retienes\na tus hijos\nEres mi proveedor", "id": "5883d0d4-882b-693c-4cb9-fd90676ee2dc"}, {"choir": "/Te doy gracias\nGrandes son tus obras,\nOh mi Dios\nTe doy gracias\nPor tu fidelidad, bondad y amor\nTe doy gracias\nMi alma te bendice hoy/", "id": "eef10ad2-d162-681b-120b-da6630d120e2"}]'::jsonb, 'TE DOY GRACIAS.json'),
('10b46c7b-b387-8b51-a701-5bf3d0b65618', 'COMPADECETE DE MÍ', 'Compadécete de mí, pues oh Dios yo clamo a ti. Y', 'A|La', '[{"id": "86a99a2d-de0b-b687-c2bd-330a39972433", "paragraph": "Compadécete de mí,\npues oh Dios yo clamo a ti.\nY con noble compasión,\nborra tú mi rebelión.\nY hazme puro en verdad,\nredimiendo mi maldad.", "chorusPos": [[0]]}, {"id": "bbfe7779-8e24-f821-4d63-9ced861769af", "paragraph": "He pecado contra ti,\ny dolor yo siento en mí.\nPues tu gracia desprecié\ny tus leyes quebranté;\nTú eres justo oh Señor,\nmas yo pobre pecador.", "chorusPos": [[0]]}, {"id": "805970f7-06ed-ae91-eec4-84269a834c30", "paragraph": "En pecado yo nací,\nnada bueno hay en mí;\nSolo en ti hay salvación,\ntú das luz al corazón.\n/Ven entonces a mi ser,\ny hazlo tu resplandecer./", "chorusPos": [[0]]}]'::jsonb, '[]'::jsonb, 'COMPADECETE DE MÍ.json'),
('5b62f5a8-7387-d2c4-a80c-e0fcccd7a479', 'DIGNO ES ÉL', '/Digno es él cordero Santo; Santo, Santo es Él, ', 'D|Re', '[{"id": "d7e93a68-6980-33bc-e4fa-dc6aadf43531", "paragraph": "/Digno es él cordero Santo;\nSanto, Santo es Él,\nlevantamos nuestra alabanza\nal que en el trono está/", "chorusPos": [[1]]}, {"id": "64a13bab-44b5-96dc-fe24-1b120e894321", "paragraph": "Digno es él cordero Santo;\nSanto, Santo es Él,\nlevantamos nuestra alabanza\nal que en el trono está", "chorusPos": [[2]]}]'::jsonb, '[{"choir": "Santo, Santo, Santo,\nDios todopoderoso quien fue quien es y quien vendrá,\nLa creación hoy canta y damos gloria a Él,\ntu eres digno por siempre y siempre", "id": "c87c51d0-4b2a-e9f5-ab84-a02e7e203942"}, {"choir": "/ Santo, Santo, Santo,\nDios todopoderoso quien fue quien es y quien vendrá,\nLa creación hoy canta y damos gloria a Él,\ntu eres digno por siempre y siempre /", "id": "52e6d72a-baf9-f2ab-9484-d44e063b9b80"}]'::jsonb, 'DIGNO ES ÉL.json'),
('638000c2-e93f-4054-a0e4-79b12163fccd', 'gracias, gracias señor', 'ME HAS TOMADO EN TUS BRAZOS    Y ...', '--', '[{"paragraph": "ME HAS TOMADO EN TUS BRAZOS \n  Y ME HAS DADO SALVACIÓN  \n DE TU AMOR HAS DERRAMADO  \n EN MI CORAZÓN"}, {"paragraph": "NO SABRÉ AGRADECERTE  \n LO QUE HAS  \n HECHO POR MI  \n SOLO PUEDO DARTE AHORA MI CANCIÓN"}, {"paragraph": "PARA DARTE LAS \n /GRACIAS, MUCHAS \n GRACIAS SEÑOR, \n  GRACIAS MI SEÑOR JESÚS/"}, {"paragraph": "/GRACIAS, MUCHAS \n GRACIAS SEÑOR, \n  GRACIAS MI SEÑOR JESÚS/"}, {"paragraph": "EN LA CRUZ DISTE TU VIDA  \n ENTREGASTE TODO ALLÍ \n VIDA ETERNA REGALASTE AL MORIR"}, {"paragraph": "POR TU SANGRE \n TENGO ENTRADA  \n ANTE EL TRONO  \n CELESTIAL \n PUEDO ENTRAR CONFIADAMENTE  \n ANTE TI"}, {"paragraph": "/GRACIAS, MUCHAS \n GRACIAS SEÑOR, \n  GRACIAS MI SEÑOR JESÚS/"}]'::jsonb, '[]'::jsonb, 'gracias, gracias señor.json'),
('5ccece97-9d6a-fd8c-bf1d-36af29cc57af', 'ERES MI TODO', 'Tu eres mi fuerza y mi poder, el gran tesoro que', '_', '[{"id": "64721e9e-c7bb-f3a3-5ea6-99a943002a5d", "paragraph": "Tu eres mi fuerza y mi poder,\nel gran tesoro que busqué,\n¡Eres mi todo, Oh Dios!\nPerla de precio sin igual,\nnunca tu amor podré dejar,\n¡Eres mi todo, Oh Dios!", "chorusPos": [[1]]}, {"id": "80a92b21-331d-fbd3-a887-70b49cdb5daf", "paragraph": "Diste tu vida allá en la cruz,\nresucitaste mi Jesús\n¡Eres mi todo, Oh Dios!", "chorusPos": [[0]]}, {"id": "ce468e83-6828-d148-3b61-065526d5c169", "paragraph": "En sequedad o en tentación,\ntu me sostienes mi Señor,\n¡Eres mi todo, Oh Dios!", "chorusPos": [[1]]}]'::jsonb, '[{"choir": "Cristo salvador, digno de adorar,\nCristo redentor digno de adorar.", "id": "041a1f83-e61f-effa-21f8-fc3ecb58cbe7"}]'::jsonb, 'ERES MI TODO.json'),
('b5551eaf-7519-baa9-0f67-22aaf0c98974', 'DIOS SUPREMO ERES', '/Dios supremo eres, Soberano en gloria. Eres inc', 'G|Sol', '[{"id": "a994c68a-f511-baf1-91d1-da302f0c7021", "paragraph": "/Dios supremo eres,\nSoberano en gloria.\nEres incomparable, en tu hermosura\nEres incomparable en tu majestad/", "chorusPos": [[1]]}]'::jsonb, '[{"choir": "/No hay otro Dios como Jehová\nNo hay otro Dios como el Señor\nNo hay en los cielos,\nNo hay en la tierra, no hay en el mar/\nDios como el Señor.", "id": "1c59c06a-f878-576d-cdf4-faa7d49daf32"}]'::jsonb, 'Dios Supremo Eres.json'),
('a2451635-a59b-4a56-9519-f136dce6b41d', 'GLORIOSO INTERCAMBIO', '¿Cómo puede ser que el bueno y justo Se hizo hom', '_', '[{"id": "bf2c799d-0ec4-f5db-b1f2-4f773521bda3", "paragraph": "¿Cómo puede ser que el bueno y justo\nSe hizo hombre y fuera a morir\npor el más vil pecador?\n\n¿Cómo siendo yo su enemigo\nel sufrimiento en mi lugar tomó\nen aquella cruz?", "chorusPos": [[1]]}, {"id": "60a11dd5-b8dc-3b76-5dd2-54e93dfdf88c", "paragraph": "¿Como es posible que en Jesús\nComo a su hijo Él me recibió\ny su nombre llevo hoy?\n\nSu perfecta vida de obediencia\nal Padre Al yo creer,\nÉl me otorgó y perdón me dio.", "chorusPos": [[2]]}]'::jsonb, '[{"choir": "Y cargo mi maldad sobre Él\nSu rectitud, por la fe, mía es\n\nAleluya, glorioso intercambio,\nOh cuan gran misterio.\nQue por gracia salvo soy\nAleluya, gloria sea a Cristo,\npor su sacrificio\nDeclarado justo soy en Él.", "id": "77234725-6e6c-b46c-1d44-b722ea66c3b5"}, {"choir": "Y cargo mi maldad sobre Él\nSu rectitud, por la fe, mía es\n\n/Aleluya, glorioso intercambio,\nOh cuan gran misterio.\nQue por gracia salvo soy\nAleluya, gloria sea a Cristo,\npor su sacrificio\nDeclarado justo soy/ …en Él.", "id": "27c9de06-f334-7776-f08b-31d08661bea4"}]'::jsonb, 'Glorioso Intercambio.json'),
('bf12719d-6be3-b7da-917d-b02ed7df98df', 'TENGO UN REFUGIO', 'Tengo un refugio en tempestad cuando aflicciones', 'C|Do', '[{"id": "91a94ef0-2cd2-fcc5-97fd-5706963a7faf", "paragraph": "Tengo un refugio en tempestad cuando aflicciones tengo\nCuando me llena mi temor mi alma en Ti descansa", "chorusPos": [[1]]}, {"id": "d16eb3e9-a7ad-8e2a-35e2-fe47915d5b85", "paragraph": "Tengo un refugio en tempestad\nsi mi pecado acusa\nCulpable soy de mi maldad,\nTu gracia aún me acepta", "chorusPos": [[2]]}, {"id": "390b9087-c4e7-9bd2-69fe-eb77dcf76dc1", "paragraph": "Tengo un refugio en tempestad\nsi temo a la tormenta\nEn mi debilidad yo sé\nTu fuerza me sustenta", "chorusPos": [[3]]}]'::jsonb, '[{"choir": "Oh Cristo, en ti me esconderé\n        Mi paz y mi consuelo\n        Nada es más grande que tu amor\n        Confortas mi tristeza", "id": "b2a4652f-efcb-476f-bb91-a10c21c04684"}, {"choir": "Oh Cristo, en ti me esconderé\n        Ya no soy condenado\n        Refugio tengo en tu cruz\n        Y salvación encuentro", "id": "4908a4f9-9b8b-3423-7e27-5efee8c68eff"}, {"choir": "/ Oh cristo, en ti me esconderé\n        Pues llevas tú mis cargas\n        Tus manos firmes me guiarán\n        Hasta llevarme al cielo /", "id": "5a5321b2-3dae-d0c5-ad22-b225b561a164"}]'::jsonb, 'TENGO UN REFUGIO.json'),
('8a497abe-e1ac-725a-1e37-b848c4298657', 'OH AMOR DE DIOS', '¡Oh amor de Dios! Su inmensidad El hombre no pod', 'A|La', '[{"id": "054b9848-9090-5c83-4185-40de9a5f970f", "paragraph": "¡Oh amor de Dios! Su inmensidad\nEl hombre no podría contar,\nNi comprender la gran verdad,\nQue Dios al hombre pudo amar.", "chorusPos": [[0]]}, {"id": "47abdab6-a327-5577-e325-aaeec8f70133", "paragraph": "Cuando el pecado entró al hogar\nDe Adán y Eva en Edén;\nDios les sacó, más prometió\nUn Salvador también.", "chorusPos": [[1]]}, {"id": "599f6e11-112f-8a41-322c-f77499158ab0", "paragraph": "Si fuera tinta todo el mar,\nY todo el cielo un gran papel,\nY cada hombre un escritor,\nY cada hoja un pincel.", "chorusPos": [[0]]}, {"id": "8442af36-b655-59f1-aed3-01c99479e081", "paragraph": "Nunca podría describir\nEl gran amor de Dios;\nQue al hombre pudo redimir\nDe su pecado atroz", "chorusPos": [[1]]}, {"id": "e346872b-8d07-1674-cf35-e7e6fa226b7a", "paragraph": "Y cuando el tiempo pasara\nCon cada reino mundanal\nY cada reino caerá\nCon cada trama y plan carnal", "chorusPos": [[0]]}, {"id": "ca7126a7-5711-fc6d-0977-382521f0ef64", "paragraph": "El gran amor del redentor\nPor siempre durara\nLa gran canción de salvación\nTu pueblo cantara", "chorusPos": [[2]]}]'::jsonb, '[{"choir": "¡Oh amor de Dios!\nBrotando está,\nInmensurable eternal;\nPor las edades durará\nInagotable raudal.", "id": "5efeec57-7981-9263-2f08-06650b4039a2"}, {"choir": "/¡Oh amor de Dios!\nBrotando está,\nInmensurable eternal;\nPor las edades durará\nInagotable raudal./", "id": "fae03991-b514-9674-e352-62691b214fcd"}]'::jsonb, 'OH AMOR DE DIOS.json'),
('2713a53f-d05f-40d3-9d72-514e69e2decc', 'Cristo es la Peña de Horeb', 'Cristo es la peña de Horeb que es...', '--', '[{"paragraph": "Cristo es la peña de Horeb que está brotando, \n agua de vida saludable para mí; \n Cristo es la peña de Horeb que está brotando, \n agua de vida saludable para mí;"}, {"paragraph": "Ven a tomarla que es más dulce que la miel, \n refresca el alma, refresca todo tu ser; \n Cristo es la peña de Horeb que está brotando, \n agua de vida saludable para mí."}, {"paragraph": "Cristo es el lirio del valle de las flores; \n él es la rosa blanca y pure de Sarón; \n Cristo es la vida y amor de los amores; \n él es la eterna fuente de la salvación."}, {"paragraph": "Ven a buscarla en tu triste condición, \n Refresca el alma, refresca todo tu ser. \n Cristo es el lirio del valle de las flores; \n él es el la rosa blanca y pura de Sarón."}]'::jsonb, '[]'::jsonb, 'Cristo es la Peña de Horeb.json'),
('7ed66d01-c0a1-426c-96da-eb50b1289f66', 'BENDITO JESUS', 'Por ti es mi clamor   Y sin ningú...', '--', '[{"paragraph": "Por ti es mi clamor \n Y sin ningún temor, \n En ti puedo confiar \n Bendito Jesús."}, {"paragraph": "Hoy puedo escuchar  \n Tu voz de sanidad, \n Restaurando mi ser \n Bendito Jesús."}, {"paragraph": "Mi deseo eres tú, mi momento de amor \n La alegría de vivir bendito Jesús. \n Eres mi fuente de amor Eres aire, Eres sol \n El latir del corazón; bendito Jesús. \n Bendito amor de mi Señor."}, {"paragraph": "Tu gracia y favor  \n Conmigo puedo ver, \n Llenando hoy mi ser \n Bendito Jesús."}, {"paragraph": "Y hoy tu voluntad  \n Se rinde a tu verdad, \n Tu amor y tu bondad \n Bendito Jesús."}, {"paragraph": "/. Mi deseo eres tú, mi momento de amor \n La alegría de vivir Bendito Jesús. \n Eres mi fuente de amor Eres aire, Eres sol, el latir del corazón; Bendito Jesús.  \n /Bendito amor de mi Señor / / /..."}]'::jsonb, '[]'::jsonb, 'BENDITO JESUS.json'),
('013b26f6-12c3-4dfc-9389-cd318ad455de', 'Gracias Cristo', 'El misterio de la Cruz no puedo c...', '--', '[{"paragraph": "El misterio de la Cruz no puedo comprender, \n la angustia que llegó a sufrir; \n El perfecto Dios su hijo entregó, \n la copa amarga Él bebió por mi."}, {"paragraph": "Tú sangre mi maldad lavó, \n ¡GRACIAS CRISTO! \n Fue satisfecha la ira de Dios, \n ¡GRACIAS CRISTO! \n Tú enemigo fui; y hoy me siento a tu mesa. \n ¡GRACIAS CRISTO!"}, {"paragraph": "Por tu sacrificio me acercaste a ti, \n quitaste toda enemistad. \n Tu gloriosa gracia derramaste en mi,  \n Tu misericordia sin igual."}, {"paragraph": "Tú sangre mi maldad lavó, \n ¡GRACIAS CRISTO! \n Fue satisfecha la ira de Dios, \n ¡GRACIAS CRISTO! \n Tú enemigo fui; y hoy me siento a tu mesa. \n ¡GRACIAS CRISTO!"}, {"paragraph": "//Amante de mi ser,  \n quiero vivir por ti.//"}, {"paragraph": "/Tú sangre mi maldad lavó, \n ¡GRACIAS CRISTO! \n Fue satisfecha la ira de Dios, \n ¡GRACIAS CRISTO!/ \n /Tú enemigo fui; y hoy me siento a tu mesa./ \n ¡GRACIAS CRISTO!"}]'::jsonb, '[]'::jsonb, 'Gracias Cristo.json'),
('ffa0c624-876c-fe02-27e6-a6a2550dc7bc', 'El me sostendra', 'Si mi fe ha de caer,         Él me sostendrá;   ', 'C|Do', '[{"id": "314dcf7b-0469-5db5-b26b-2bb2e19f8c23", "paragraph": "Si mi fe ha de caer,\n        Él me sostendrá;\n        En la tentación yo se,\n        Él me sostendrá.\n        No podría estar de pie\n        En la oscuridad,\n        Pues mi amor muy frágil es,\n        Él me sostendrá.", "chorusPos": [[1]]}, {"id": "14b5f7ef-f54e-193f-92ac-d415f484f270", "paragraph": "Él se goza en quien salvó,\n        Él me sostendrá;\n        Ante Él precioso soy,\n        Él me sostendrá.\n        Sus promesas fieles son,\n        Mi alma guardará;\n        Alto precio Él pagó, Él me sostendrá.", "chorusPos": [[1]]}, {"id": "148df426-90e1-3175-e493-5ec4cea1ed37", "paragraph": "Él sufrió y por mí murió:\n        Él me sostendrá;\n        La justicia Él cumplió,\n        Él me sostendrá.\n        Vida eterna tengo en Él,\n        Él me sostendrá;\n        Hasta que le pueda ver;\n        ¡Él regresará!", "chorusPos": [[1]]}]'::jsonb, '[{"choir": "Él me sostendrá,\n        Él me sostendrá;\n        Pues ama tanto el Salvador,\n        Él me sostendrá.", "id": "7deef82f-6344-833b-209f-ff0020865011"}]'::jsonb, 'El me sostendra.json'),
('cfe07500-3b33-4c88-af93-e56f9204dc2a', 'gracia y paz', 'GRACIA   Y PAZ...', '--', '[{"paragraph": "GRACIA \n Y PAZ"}, {"paragraph": "Gracia y paz ¿Cómo puede ser? \n Para el transgresor \n Y al ladrón sin valor \n Dices que nuestro juicio es morir \n Por la eternidad \n En dolor y sin Ti \n Oh qué gran misterio es para mí \n Qué gran misterio es para mí \n Que tu gracia vino a mí"}, {"paragraph": "Gracia y paz ¿Cómo puede ser? \n Que el perfecto Rey \n Con su sangre pagó \n ¡Qué expiación tan grandiosa Tú das! \n Que al más vil pecador \n Puede limpiar y librar \n Oh qué gran misterio es para mí \n Qué gran misterio es para mí \n Que tu gracia vino a mí"}, {"paragraph": "Gracia y paz ¿Cómo puede ser? \n Canción de gratitud \n Cantaré sin parar \n Apartado y amado por Dios \n Satisfecho estoy \n En Jesús, mi Señor \n Oh qué gran misterio es para mí \n Qué gran misterio es para mí \n Que tu gracia vino a mi"}, {"paragraph": "/Oh, maravilloso amor por mí \n Maravilloso amor por mí \n Que tu gracia vino a mí/"}]'::jsonb, '[]'::jsonb, 'gracia y paz.json'),
('fab06f89-7260-4f41-a37b-9501fdb719c0', 'Co cristo  hay alegria lo tienes que probar', 'CON CRISTO HAY ALEGRÍA LO TIENES ...', '--', '[{"paragraph": "CON CRISTO HAY ALEGRÍA LO TIENES QUE PROBAR  \n ENTRÉGALE TU VIDA Y ASI PODRAS CANTAR"}, {"paragraph": "YA NO  TIENES QUE SUFRIR  \n YA NO TIENES QUE LLORAR \n EL VINO PARA DARTE PAZ  \n Y FELICIDAD"}, {"paragraph": "Co cristo  hay alegria lo tienes que probar  \n entrégale tu vida y asi podras cantar  \n ya no  tienes que sufrir  \n ya no tienes que llorar \n el vino para darte paz y felicidad"}, {"paragraph": "si no tienes a Cristo no te podrás salvar"}, {"paragraph": "Co cristo  hay alegria lo tienes que probar  \n entregale tu voida y asi podras cantar ya no  tienes que sufrir  \n ya no tienes que llorar \n el vino para darte paz y felicidad \n en"}]'::jsonb, '[]'::jsonb, 'Co cristo  hay alegria lo tienes que probar.json'),
('33a28fe4-1e17-4193-8331-32629035cde6', 'Aunque te pienso que tu no existías', 'Aunque te pienso que tu no existí...', '--', '[{"paragraph": "Aunque te pienso que tu no existías vengo a ti a buscar aquella salida  \n se muy bien que eres para mi \n un amor de  \n solo te  \n pero yo se que es  \n entra a mi vida ven a mi corazón  \n con un toque a mi vida todo cambiara \n aquel amor es aquel que yo asi sufria  \n mi salvador"}, {"paragraph": "Aunque tu pienso que tu no existia vengo a ti a buscar aquella salida  \n se muy bien que eres para mi \n pero yo se que es  \n entra a mi vida ven a mi corazon  \n con un toque a mi vida todo cambiara \n aquel amor es aquel que yo asi sufria  \n mi salvador"}]'::jsonb, '[]'::jsonb, 'Aunque te pienso que tu no existías.json'),
('68a81e20-d0c4-44a4-8506-2d553668fc0a', 'EL PODER DE CRISTO N. 10', 'El poder de Cristo fue manifestad...', '--', '[{"paragraph": "El poder de Cristo fue manifestado, \n Por las grandes obras de su creación."}, {"paragraph": "Cristo es Poderoso para redimir \n Él ha preparado para los salvados \n Un glorioso hogar"}, {"paragraph": "El poder de Cristo puede darte vida \n Si tu lo recibes en tu corazón."}, {"paragraph": "Cristo es Poderoso para redimir \n Él ha preparado para los salvados \n Un glorioso hogar"}, {"paragraph": "El poder de Cristo siempre nos anima \n Para andar la vida sin mirar atrás"}, {"paragraph": "Cristo es Poderoso para redimir \n Él ha preparado para los salvados \n Un glorioso hogar"}]'::jsonb, '[]'::jsonb, 'EL PODER DE CRISTO N. 10.json'),
('128215b2-0894-4d2d-90fe-4daf172e0123', 'Doxologia (Judas 24-25)', 'DOXOLOGÍA   (JUDAS 1:24-25)...', '--', '[{"paragraph": "DOXOLOGÍA \n (JUDAS 1:24-25)"}, {"paragraph": "/Y aquel que es poderoso para guardaros,  \n para guardaros sin caída,  \n y presentaros sin mancha delante de Su gloria,  \n con gran alegría./"}, {"paragraph": "/Al único y sabio Dios nuestro salvador, \n  sea gloria y majestad, imperio y potencia,  \n ahora y por todos los siglos. \n Amén./"}, {"paragraph": "/Aaaamén, \n Aaaamen, \n ahora y por todos los siglos. \n Amén./"}]'::jsonb, '[]'::jsonb, 'Doxologia (Judas 24-25).json'),
('0d4e00e0-50c3-4e76-8c4b-25fcf07d7d95', 'DIOS ETERNO', 'MIL VECES TE FALLE , MAS TU FUIST...', '--', '[{"paragraph": "MIL VECES TE FALLE , MAS TU FUISTE FIEL TU GRACIA ME LEVANTO, ME BASTA TU AMOR  \n DIOS ETERNO TU LUZ POR SIEMPRE BRILLARA  \n Y TU GLORIA INCOMPARABLE SIN FINAL"}, {"paragraph": "DIOS ETERNO TU LUZ  \n POR SIMPRE BRILLARA  \n EN TU GLORIA INCOMPARABLE  \n SIN FINAL \n Y EL CLAMOR DE MI SER  \n \tES POR TI TE DOY MI ALMA"}, {"paragraph": "SEÑOR TU VOLUNTAD PERMANECERÁ  \n EN TI ME QUIERO PERDER EN ADORACION  \n DIOS ETERNO TU LUZ SIMEPRE BRILLARA \n Y TU GLORIA INCOMPARABLE SIN FINAL"}, {"paragraph": "DE MI CORAZON DE DOY EL CONTROL  \n CONSUME TODO MI INTERIOR, DIOS  \n TU JUSTICIA Y AMOR ME ABRAZA SEÑOR  \n TE AMO DESDE MII NTERIOR"}, {"paragraph": "DIOS ETERNO TU LUZ POR SIMPRE BRILLARA  \n EN TU GLORIA INCOMPARABLE SIN FINAL"}, {"paragraph": "EN MI CORAZON TE DOY EL CONTROL CONSUME TODO MI NTERTIO R \n JUSTICIA Y AMOR ME ABRAZA SELO DESDE MI INTERIOR"}]'::jsonb, '[]'::jsonb, 'DIOS ETERNO.json'),
('aa689176-6baa-474d-87da-e172aa845578', 'alabare', '//ALABARE, ALABARE//    ALABARE A...', '--', '[{"paragraph": "//ALABARE, ALABARE//  \n ALABARE A MI SEÑOR \n JUAN VIO EL NUMERO DE LOS REDIMIDOS"}, {"paragraph": "Y TODOS ALABABAN  AL SEÑOR  \n UNOS ORABAN Y OTROS CANTABAN  \n Y TODOS ALABABAN AL SEÑOR."}]'::jsonb, '[]'::jsonb, 'alabare.json'),
('a4d29ce1-389b-361f-0149-732bc9ce7b53', 'EL SEÑOR ES MI PASTOR', 'El Señor es mi pastor Nada a mí me faltara En su', 'A|La', '[{"id": "7886103f-da7d-5d09-217b-a4ab1497db6d", "paragraph": "El Señor es mi pastor\nNada a mí me faltara\nEn sus verdes pastos\nMe hace descansar\n\nDe sus aguas me dará\nMi alma el restaurara\nPor senderos de justicia me guiara\nPor amor de su nombre", "chorusPos": [[1]]}, {"id": "6f008a88-e495-421e-cf58-6d96ea2d83e6", "paragraph": "El Señor es mi pastor\nNo hay razón para el temor\nPues su vara me da aliento y protección\n\nSi en el valle de aflicción\nMe rodea la opresión\nEl conmigo esta y bendecido soy\nPor amor de su nombre", "chorusPos": [[1]]}, {"id": "dc36e5fe-3fcc-7682-2672-f7699d45878f", "paragraph": "//Misericordia y bien me seguirán\nTu plenitud me saciara\nEn tu morada por la eternidad//", "chorusPos": [[1]]}]'::jsonb, '[{"choir": "Jamás me dejaras\nEn tu fidelidad, Jesús\nConfiado esta mi corazón\n\nDe ti dependeré\nTu voz escuchare, Jesús\nTe seguiré, mi buen pastor", "id": "c42c8f89-422f-a4ea-6fef-7dddf58d51f3"}]'::jsonb, 'EL SEÑOR ES MI PASTOR.json'),
('ee3b9120-e614-4fa3-8a26-7402ceef67e6', 'EL  GOZO QUE TENGO YO', 'EL  GOZO QUE TENGO YO    /EL MUND...', '--', '[{"paragraph": "EL  GOZO QUE TENGO YO  \n /EL MUNDO NO ME LO DIO/ COMO NO ME LO DIO  \n NO ME LO PUEDE QUITAR \n SI EMPEZAMOS A ORAR"}, {"paragraph": "SI EMPEZAMOS A ORAR \n CLAMAREMOS A JEHOVA  \n SI EMPEZAMOS A ORAR  \n ESTE MUNDO TIEMBLA \n ELIAS ORO EL FUEGO CAYO \n ORO JOSUE EL SOL SE PARO"}]'::jsonb, '[]'::jsonb, 'EL  GOZO QUE TENGO YO.json'),
('e04bcad5-e281-4676-aa83-47ffb1115b5f', 'Amigos-Daniel Calveti', 'DESDE CHICOS APRENDIMOS, AL QUERE...', '--', '[{"paragraph": "DESDE CHICOS APRENDIMOS, AL QUERERNOS COMO HERMANOS, \n EL FUTBOL Y LAS CANICAS, A LOS BUENOS Y A LOS MALOS"}, {"paragraph": "MUCHAS VECES NOS PELEAMOS, OTRAS VECES NI HABLAMOS, \n PERO AUN SIGO SIENDO AMIGO, DEL QUE ES COMO MI HERMANO."}, {"paragraph": "AMIGO TU, AMIGO YO \n PERDONAME SI TE HE FALLADO, \n LO SE MUY BIEN, \n  LO SABES TÚ,  \n QUIERO ESTAR Y COMPARTIR,"}, {"paragraph": "MOMENTOS BUENOS Y LOS MALOS, \n QUIERO REIR, TAL VEZ LLORAR, \n AMIGOS QUE.....NUNCA OLVIDAMOS."}, {"paragraph": "EN MOMENTOS PRESENTIMOS, QUE SOLOS NOS ENCONTRAMOS,  \n ES ALLÍ DONDE APARECEN, LOS QUE SON MAS QUE HERMANOS."}, {"paragraph": "LOS REGALITOS QUE NOS DAMOS,  \n LAS PALABRAS QUE CALLAMOS, \n LOS ABRAZOS QUE NEGAMOS, AL QUE HOY NO ESTÁ A TU LADO,"}, {"paragraph": "PERO AUN AFUERA HAY MUCHOS, ESPERANDO DE UN ABRAZO, \n NECESITAN DE AQUEL, QUE SE A DE LLAMAR HERMANO."}]'::jsonb, '[]'::jsonb, 'Amigos-Daniel Calveti.json'),
('31c48d6e-d35d-4e7c-85fa-c807e88e4adb', 'ALGO ESTA CAYENDO AQUÍ', 'ALGO ESTA CAYENDO AQUÍ   ALGO EST...', '--', '[{"paragraph": "ALGO ESTA CAYENDO AQUÍ \n ALGO ESTA CAYENDO AQUÍ \n ES TAN FUERTE SOBRE MI \n MIS MANOS LEVANTARÉ \n Y SU GLORIA TOCARÉ"}, {"paragraph": "ESTA CAYENDO \n SU GLORIA SOBRE MI \n SANANDO HERIDAS \n LEVANTANDO AL CAIDO \n SU GLORIA ESTÁ AQUÍ \n SU GLORIA ESTA AQUÍ"}, {"paragraph": "LEVANTO MIS MANOS \n LEVANTO MIS MANOS \n AUNQUE NO TENGA FUERZAS \n LEVANTO MIS MANOS \n AUNQUE TENGA MIL PROBLEMAS"}, {"paragraph": "CUANDO LEVANTO MIS MANOS \n COMIENZO A SENTIR \n UNA UNCIÓN QUE ME HACE CANTAR \n CUANDO LEVANTO MIS MANOS \n COMIENZO A SENTIR  \n EL FUEGO"}, {"paragraph": "CUANDO LEVANTO MIS MANOS \n MIS CARGAS SE VAN \n NUEVAS FUERZAS TU ME DAS \n TODO ESO ES POSIBLE \n TODO ESO ES POSIBLE \n CUANDO LEVANTO MIS MANOS"}, {"paragraph": "FUENTE DE VIDA \n SEPARADO DE TI… NO SOY NADA \n ALEJADO DE TI.. MUERO \n SI TU NO ESTAS EN MI YO DESESPERO \n PIERDO LA ESPERANZA \n MUERE EL ANHELO"}, {"paragraph": "COMO VOY ALEJARME DE TI  \n FUENTE DE VIDA \n TU ME DISTE LA ALEGRIA \n COMO VOY A SEPARARME DE TI  \n MI DIOS Y MI GUIA \n SI SOLO TU TIENES PALABRAS..  \n DE VIDA"}, {"paragraph": "PRECIOSO JESUS \n AL CONTEMPLAR TU OBRA EN LA CRUZ \n TANTO AMAR DERRAMADO \n Y TODO POR MI \n CON GRATITUD ME QUIERO ACERCAR \n SOLO TENGO MI VIDA ….ACEPTALA"}, {"paragraph": "NO SE COMO EXPRESARME ANTE TU HERMOSURA \n RODEADA DE GLORIA Y PODER \n NECESITO DECIRTE  \n LO QUE SIENTO AHORA \n ME ACERCO A TI.. AL SANTO LUGAR"}, {"paragraph": "PRECIOSO JESUS, MI REDENTOR \n AMADO SEÑOR, ERES TODO PARA MI \n TE ADORARE CADA DIA DE MI VIDA \n NO PUEDO VIVIR SI NO ESTAS JUNTO A MI"}, {"paragraph": "BENDITO SEÑOR \n POR TI ES MI CLAMOR \n Y SIN NINGUN TEMOR \n EN TI PUEDO CONFIAR \n BENDITO JESUS"}, {"paragraph": "HOY PUEDO ESCUCHAR \n TU VOZ DE SANIDAD \n RESTAURANDO MI SER \n BENDITO JESUS"}, {"paragraph": "MI DESEO ERES TU \n MI MOMENTO MI AMOR \n LA ALEGRIA DE VIVIR \n BENDITO JESUS"}, {"paragraph": "ERES MI FUENTE DE AMOR \n ERES AIRE ERES SOL \n EL LATIDO  DE MI CORAZON  \n BENDITO JESUS \n BENDITO AMOR DE MI SEÑOR"}, {"paragraph": "TU GRACIA Y FAVOR \n CONTIGO PUEDO VER \n LLENANDO HOY MNI SER \n BENDITO JESUS"}, {"paragraph": "Y HOY TU VOLUNTAD  \n SE RINDE A TU VERDAD \n TU AMOR Y TU BONDAD \n BENDITO JESUS"}, {"paragraph": "DIGNO Y SANTO \n DIGNO ES EL \n CORDERO SANTO \n SANTO, SANTO, ES ÉL"}, {"paragraph": "LEVANTAMOS  \n NUESTRA ALABANZA \n AL QUE EN EL TRONO ESTÁ"}, {"paragraph": "SANTO, SANTO, SANTO, \n DIOS TODOPODERESO \n QUIEN FUE, QUIEN ES  \n Y QUIEN VENDRA \n LA CREQACION TE CANTA  \n Y DAMOS GLORIA A ÉL \n TU ERES DIGNO  \n POR SIEMPRE Y SIEMPRE"}, {"paragraph": "CUENTA CONMIGO \n Y A TRAVES DE LAS  \n GENERACIONES \n VIVIENDO DIFERENTES SITUACIONES \n TUS HIJOS  \n HAN LLEVADO TU PALABRA  \n A PUEBLOS CIUDADES Y NACIONES"}, {"paragraph": "ALGUNOS HAN DADO  \n SU PROPIA VIDA \n Y OTROS VIVEN  \n LEJOS DE SU FAMILIA \n TAMBIEN HAY DE LOS QUE  \n LO HAN DEJADO TODO \n PARA QUE SEPAN QUE TU JESUS \n  ERES LA ALTERNATIVA"}, {"paragraph": "Y YO NO SE SI MI SITUACION  \n SERA DIFICIL O MAS FACIL \n PERO JESUS YO TE DIGO HOY \n CUENTA CONMIGO,  \n PARA ALCANZAR ESTA GENERACION \n CUENTA CONMIGO  \n ME PERTENECE ESTA GENERACION"}]'::jsonb, '[]'::jsonb, 'ALGO ESTA CAYENDO AQUÍ.json'),
('6b057cc9-e01b-407d-afe3-035155bda949', 'EN LA CRUZ DE JESUS', 'En el monte calvario estaba una c...', '--', '[{"paragraph": "En el monte calvario estaba una cruz, \n Emblema de afrenta y dolor; \n Mas yo amo esa cruz do murió mi Jesús. \n Por salvar al más vil pecador."}, {"paragraph": "¡Oh!, yo siempre amare esa cruz: \n Mi corona Jesús me dará. \n Y algún día en vez de una cruz, \n Que en sus triunfos mi gloria será;"}, {"paragraph": "Y aunque el mundo desprecie \n La cruz de Jesús, para mi tiene \n Suma atracción; pues en ella llevo \n El cordero de Dios de mi alma la Condenación."}, {"paragraph": "¡Oh!, yo siempre amare esa cruz: \n Mi corona Jesús me dará. \n Y algún día en vez de una cruz, \n Que en sus triunfos mi gloria será;"}, {"paragraph": "En la cruz de Jesús do su sangre vertió, \n Hermosura contemplo sin par; \n Pues en ella triunfante a la muerte venció \n Y me ser puede santificar."}, {"paragraph": "¡Oh!, yo siempre amare esa cruz: \n Mi corona Jesús me dará. \n Y algún día en vez de una cruz, \n Que en sus triunfos mi gloria será;"}, {"paragraph": "Para siempre su gloria veré \n Sus desprecios con el llevare, y algún \n Día feliz con los santos en luz \n Yo seré siempre fiel a la cruz de Jesús."}, {"paragraph": "¡Oh!, yo siempre amare esa cruz: \n Mi corona Jesús me dará. \n Y algún día en vez de una cruz, \n Que en sus triunfos mi gloria será;"}]'::jsonb, '[]'::jsonb, 'EN LA CRUZ DE JESUS.json'),
('ed8a2c7f-802c-403c-89bc-28af26951347', 'EN LA CRUZ N.322', 'Me hirió el pecado, fui a Jesús, ...', '--', '[{"paragraph": "Me hirió el pecado, fui a Jesús, \n Mostréle mi dolor. \n Perdido errante vi su luz, \n Bendíjome en su amor"}, {"paragraph": "En la cruz, en la cruz, do primero ví la luz,  \n Y las manchas de mi alma, Él lavó \n Fui allí por la fe do ví a Jesús \n  y siempre feliz con Él seré"}, {"paragraph": "Venció la muerte con poder \n Y el padre lo exalto \n Confiar en cristo es mi placer  \n morir no temo yo."}, {"paragraph": "En la cruz en la cruz do primero vi la luz  \n Y las manchas de mi alma el lavo \n Fui ahí por la fe do vi a Jesús \n  y siempre feliz con el seré"}, {"paragraph": "Aunque el se fue conmigo esta  \n el gran consolador \n Divino espíritu que hoy  \n me da perfecto amor"}, {"paragraph": "En la cruz en la cruz do primero vi la luz  \n Y las manchas de mi alma el lavo \n Fui ahí por la fe do vi a Jesús \n  y siempre feliz con el seré"}]'::jsonb, '[]'::jsonb, 'EN LA CRUZ N.322.json'),
('10d45d36-aa2f-9875-fd84-0772644bff46', 'LA GLORIA DE LA CRUZ', '¿Cómo es que en Su perfecto plan mi pecado perdo', 'E|Mi', '[{"id": "9817217a-a0f4-f395-4b5c-2c353b6348a9", "paragraph": "¿Cómo es que en Su perfecto\nplan mi pecado perdonó,\ncuando al morir mi culpa,\n¿el Cordero la llevó?", "chorusPos": [[0]]}, {"id": "fd03b4b7-7f1d-c2e2-8513-f5ef2a765ace", "paragraph": "¿Cuán Sabio y Soberano Dios\nSu gloria mostrará,\ncuando en Su trono,\nel pecador se regocijará?", "chorusPos": [[1]]}, {"id": "b6041dc2-dd4f-866a-8032-71403bec68be", "paragraph": "Qué rectitud Él reveló,\nlibrando al pecador,\ny al culpable perdonó,\nsus manchas Él lavó.", "chorusPos": [[0]]}, {"id": "27a0a508-b0d7-c295-e862-cee0d504e360", "paragraph": "Tu sacrificio propició,\nla ira del Señor,\ny por tu muerte y expiación,\nhoy tengo redención.", "chorusPos": [[1]]}, {"id": "e5b1c0fd-857c-e902-d820-35e2d4fb5d12", "paragraph": "Que gracia para aquellos que,\nhabrían de creer,\namor inagotable que\nno puedo comprende", "chorusPos": [[0]]}, {"id": "7e72a0eb-4286-d6d2-e6c1-2ce3c6f5b63f", "paragraph": "La gracia que me perdonó,\nTu hijo ahora soy\nAmado por la eternidad\nPor lo que hiciste oh Dios", "chorusPos": [[1]]}]'::jsonb, '[{"choir": "Oh, la Gloria de la Cruz,\nTu Hijo enviaste a morir.\nMi vida dejaré atrás, para conocer\nla gloria de, la gloria de la cruz.", "id": "e9b35b98-748a-3638-044e-c1582a48bff1"}]'::jsonb, 'LA GLORIA DE LA CRUZ.json'),
('3b1aef0f-ea4d-ed4b-c29d-4163acf18ab7', 'MIENTRAS TENGA ALIENTO', 'Como agradezco Señor Tomaste en la cruz mi lugar', '_', '[{"id": "9687c573-42ef-ac05-06d8-75e13c0ff8a3", "paragraph": "Como agradezco Señor\nTomaste en la cruz mi lugar.\nComo agradezco Señor\nTu gran amor y bondades.\nPor acercarme a ti, por permitirme oír,\ny abrir mi corazón al evangelio.", "chorusPos": [[1]]}, {"id": "4ff29b1d-bf63-650e-0304-3c78a4319baa", "paragraph": "Como agradezco Señor\npor tanto, amor en tus ojos.\ncomo agradezco Señor\nel cambio que has hecho en mí.\npor darme tu poder, tu gozo y tu favor,\ny permitirme ver tus bondades.", "chorusPos": [[1]]}, {"id": "78c3ceaa-4765-4960-4ee3-c55ac0fe031e", "paragraph": "Como agradezco Señor\nTomaste en la cruz mi lugar.\nComo agradezco Señor\nTu gran amor y bondades.\nPor acercarme a ti, por permitirme oír,\ny abrir mi corazón al evangelio.", "chorusPos": [[1]]}]'::jsonb, '[{"choir": "//Mientras tenga aliento te alabare,\nMientras viva te cantare,\nMientras lata mi corazón te bendeciré//.", "id": "e25f4560-6615-6f78-aa67-28aafc1360d7"}]'::jsonb, 'MIENTRAS TENGA ALIENTO.json'),
('a5ccbbcf-700b-466c-807f-c19e97d72f70', 'GRANDE, PODEROSO,!OH! DIOS TU', 'TE ALABARE,DANDO UNA VUELTA TE EX...', '--', '[{"paragraph": "TE ALABARE,DANDO UNA VUELTA TE EXALTARE,ALSANDO MIS MANOS TU NOMBRE ALABARE SIEMPRE"}, {"paragraph": "POR QUE TU JEHOVA  ME HAS LIBRADO DE TODO MAL, DESATASTE MIS SILICIOS ME SEÑISTE DE VERDAD \n HOY TU NOMBRE JESUS.. ALABARE SIEMPRE"}]'::jsonb, '[]'::jsonb, 'GRANDE, PODEROSO,!OH! DIOS TU.json'),
('f4669fbe-9086-7577-a64d-87d181bdabab', 'NO HAY OTRO', 'Un pueblo que nunca se postran Que no se conform', 'C|Do', '[{"id": "d801b2a1-b19f-1b0e-257f-d4dd82e66ffb", "paragraph": "Un pueblo que nunca se postran\nQue no se conforman al mundo y su placer.\n\nUn pueblo de vida consagrada\nY corazón que busca tu gloria conocer.", "chorusPos": [[0]]}, {"id": "13d1383e-5db9-42bd-8504-bd66157a9a72", "paragraph": "Un pueblo creen tu palabra llenos de valor\nY profunda convicción\n\nUn pueblo firmes en la roca que tu\nVerdad proclaman con gran pasión", "chorusPos": [[1]]}, {"id": "27a86c81-fa06-b28b-5820-64f279d3ef7d", "paragraph": "Fieles discípulos de Cristo\nQue al reino de los cielos le dieron su lealtad\n\nSiervos que ante él se postran\nY por el evangelio su vida dan", "chorusPos": [[1]]}, {"id": "30bd6de1-f207-cd4f-59fb-bd97098d72b2", "paragraph": "/Mueve hoy Señor nuestro corazón\nHazlo atento a tu verdad…\nVen renuévanos y confórmanos\nPara hacer tu voluntad/", "chorusPos": [[2]]}]'::jsonb, '[{"choir": "Confesamos que tú eres nuestro Dios\nNo hay otro, no hay otro\nSeguiremos el llamado de tu voz\nNo hay otro, no hay otro", "id": "ffc4adc1-3d47-82b3-7dfd-9f66acdccd3c"}, {"choir": "/Confesamos que tú eres nuestro Dios\nNo hay otro, no hay otro\nSeguiremos el llamado de tu voz\nNo hay otro, no hay otro./", "id": "0b99dbf9-2b84-f767-c9c3-8fae68343afe"}]'::jsonb, 'NO HAY OTRO.json'),
('dce16c12-d672-87e1-fa88-ad3f80083d4f', 'ES EXALTADO', 'Es exaltado en lo alto exaltado es el Rey. Le al', 'A|La', '[{"id": "08375bfb-c1bc-e85d-046b-ca02396ea829", "paragraph": "Es exaltado en lo alto exaltado es el Rey.\nLe alabaré.\nEs exaltado por siempre exaltado\nY yo le alabaré.", "chorusPos": [[1]]}, {"id": "532ff07c-6a0b-caa8-4872-155aa8ec7972", "paragraph": "Majestad, te adoro majestad\nDoy a Cristo toda gloria alabanza y honor.\nMajestad, reino y autoridad.\nDesde tu trono fluye por siempre tu majestad.", "chorusPos": [[2]]}, {"id": "9c0f11dc-11eb-ea6c-efe7-febb09ca7596", "paragraph": "", "chorusPos": [[1], [2]]}]'::jsonb, '[{"choir": "Él es Señor, por siempre reinarás\nSu creación en él se gozará\n//Es exaltado en lo alto exaltado es el Rey//", "id": "b91c7d8f-0f2c-bf5c-4244-5a2e1a1b27ff"}, {"choir": "Alabad y exaltad el nombre de Cristo\nMagnificad y glorificad a Cristo el Rey.\nMajestad, te adoro majestad,\n//Aquel que murió y resucitó es Rey mi Señor//", "id": "d05a64dc-9314-36cb-cf48-acdc8ca74ca8"}]'::jsonb, 'ES EXALTADO.json'),
('b7c4c48f-0e09-4e03-910d-3f581eaca3f9', 'DALE PALMAS,', 'DALE PALMAS,   OTRA VEZ,   AL SEÑ...', '--', '[{"paragraph": "DALE PALMAS, \n OTRA VEZ, \n AL SEÑOR LE SATISFACE, \n DALE PALMAS"}, {"paragraph": "ALLI DONDE ESTAS PARADO \n MIRA QUIEN ESTA A TU LADO \n  DALE UNA SONRISITA \n AL SEÑOR LE SATISFACE DALE PALMAS"}, {"paragraph": "ALLI DONDE ESTAS PARADO \n MIRA QUIEN ESTA A TU LADO \n  DALE UNA PELLISCON \n AL SEÑOR LE SATISFACE DALE PALMAS"}, {"paragraph": "ALLI DONDE ESTAS PARADO \n MIRA QUIEN ESTA A TU LADO \n  DALE UNA SONRISITA \n AL SEÑOR LE SATISFACE DALE PALMAS"}, {"paragraph": "ALLI DONDE ESTAS PARADO \n MIRA QUIEN ESTA A TU LADO \n  DALE UNA SONRISITA \n AL SEÑOR LE SATISFACE DALE PALMAS"}]'::jsonb, '[]'::jsonb, 'DALE PALMAS,.json'),
('e19368f7-e87a-4f48-a251-910186b359e9', 'CONTENDAMOS N. 90', 'Contendamos, jóvenes por la fe   ...', '--', '[{"paragraph": "Contendamos, jóvenes por la fe \n Aunque brance el mundo con satanás; \n En la lucha nunca nos vencerán, \n Pues Jesús nos guardará."}, {"paragraph": "Si sufrimos aquí, reinaremos alli \n En la gloria celestial. \n Si llevamos la cruz por amor de Jesús \n La corona El nos dará"}, {"paragraph": "No seamos tibios de Corazón, \n Ni dejemos nunca el primer amor; \n Mantengamos firme la profesión \n De la fe en Salvador."}, {"paragraph": "Si sufrimos aquí, reinaremos alli \n En la gloria celestial. \n Si llevamos la cruz por amor de Jesús \n La corona El nos dará"}, {"paragraph": "Procuremos todos la santidad, \n Sin la cual ninguno verá al Señor; \n Gozo, Paz y eterna felicidad \n Cristo ofrece  al vencedor."}, {"paragraph": "Si sufrimos aquí, reinaremos alli \n En la gloria celestial. \n Si llevamos la cruz por amor de Jesús \n La corona El nos dará"}]'::jsonb, '[]'::jsonb, 'CONTENDAMOS N. 90.json'),
('78584873-d702-0489-5ac1-7dffae419280', 'SOLO EN JESÚS', 'Solo en Jesús esta mi fe, mi esperanza y mi canc', 'D|Re', '[{"id": "8013ccb8-8aa5-bfe8-9755-5e7c28b1c199", "paragraph": "Solo en Jesús esta mi fe,\nmi esperanza y mi canción.\nPiedra angular firme y sostén\ninconmovible en la aflicción.", "chorusPos": [[1]]}, {"id": "03be6167-b2bb-5818-6952-d2b5063bad1b", "paragraph": "Solo en Jesús hijo de Dios\nquien se humilló por nuestro bien.\nCordero de mi salvación\npor este mundo herido fue.", "chorusPos": [[2]]}, {"id": "56e731fb-42ed-52a5-f611-1320aa05cc09", "paragraph": "En un sepulcro el yació,\nel cuerpo inerte del Señor.\nMas el tercer día llegó\nresucitó en gloriosa luz", "chorusPos": [[3]]}, {"id": "a3362ff4-b58c-4f11-22f0-ba653dcef9f2", "paragraph": "Desde al nacer hasta el morir\nSea el poder de Cristo en mi.\nNo temeré seguro estoy\nmi vida yo a Él le doy.", "chorusPos": [[4]]}]'::jsonb, '[{"choir": "Cuán grande amor inmensa paz\nen el temor o adversidad.\nConsolador amigo fiel\nyo en su amor me sostendré.", "id": "fa7bd1e4-2c1a-8d4f-3e65-e69e84fb12c7"}, {"choir": "En una cruz fue a morir\nY Dios mostro su gracia ahí\npues mi pecado Él llevo\nen su aflicción vida me dio.", "id": "a711861c-e1ce-c161-a705-2a2f72bf684b"}, {"choir": "Y al triunfar sobre el mal\nperdió el pecado potestad\nDe Él suyo soy, Él mío es.\nPues con su sangre me compró.", "id": "077f0028-b478-ad3f-8704-37ee6275b796"}, {"choir": "/Ningún poder ningún afán\nde Él me arrebatara.\nHasta que Él venga otra vez\nen su poder me sostendré/.", "id": "d7bd9ecd-e406-d661-17b4-323ed0eba145"}]'::jsonb, 'SOLO EN JESÚS.json'),
('074c0c32-3523-fa44-a7a1-4c18c66e87ee', 'MIRAD CUAL AMOR', 'Mirad cual amor nos ha dado el Padre al hacernos', 'A|La', '[{"id": "2d026d1f-9e05-b82a-bbc2-b944a487f0c9", "paragraph": "Mirad cual amor\nnos ha dado el Padre\nal hacernos\nhijos de Dios", "chorusPos": [[1]]}]'::jsonb, '[{"choir": "///Para ser llamados\nhijos de Dios///", "id": "bae4fe9f-b3df-1ab0-c324-3460c679e700"}]'::jsonb, 'MIRAD CUAL AMOR.json'),
('ea94fd3c-52d5-4c38-93d2-753bf402e1a3', 'COMO NO CANTARTE SEÑOR', 'COMO NO CANTARTE SEÑOR   COMO NO ...', '--', '[{"paragraph": "COMO NO CANTARTE SEÑOR \n COMO NO ALABARTE MI REY \n COMO NO DECIRTE QUE TE AMO \n SI ESTOY ENAMORADO DE  TI"}, {"paragraph": "ES POR ESO QUE YO TE ALABO \n Y ES POR ESO QUE TE SIRVO"}, {"paragraph": "COMO NO GOZARME SEÑOR \n COMO NO ALEGRARME  \n MI REY \n Y CUANDO PERDIDO  \n YO ESTABA \n SOLO TU ME AMASTE JESUS"}]'::jsonb, '[]'::jsonb, 'COMO NO CANTARTE SEÑOR.json'),
('e30fa89b-2d38-4549-9648-3c8efa0c3b40', 'DESDE MI INTERIOR', 'MIL VECES TE FALLE MAS TU FUISTE ...', '--', '[{"paragraph": "MIL VECES TE FALLE MAS TU FUISTE FIEL  \n TU GRACIA ME LEVANTO  \n ME VASTA TU AMOR"}, {"paragraph": "DIOS ETERNO TU LUZ SIEMPRE BRILLARA  \n Y TU GLORIA INCOMPARABLE SIN FINAL"}, {"paragraph": "SEÑOR TU VOLUNTAD PERMANECERA \n EN TI ME QUIERO PERDER EN ADORACIÓN"}, {"paragraph": "Y DE MI CORAZÓN TE DOY EL CONTROL \n CONSUME TODO MI INTERIOR \n DIOS"}, {"paragraph": "JUSITICIA y amor me abrazan señor  \n te amo desde mi interior"}, {"paragraph": "/Dios eterno tu luz siempre brillara y tu gloria incomparable sin final  \n Y el clamor de mi ser contigo siempre estará \n desde mi interior mi alma clamara/"}]'::jsonb, '[]'::jsonb, 'DESDE MI INTERIOR.json'),
('b1658385-a7ff-40e5-8413-d6a937df11f3', 'Consagrarme Todo Entero #462', 'CONSAGRARME TODO ENTERO   (#462)...', '--', '[{"paragraph": "CONSAGRARME TODO ENTERO \n (#462)"}, {"paragraph": "Consagrarme todo entero \n alma, vida y corazón, \n es el intimo deseo, \n que hoy me anima, buen Señor."}, {"paragraph": "Héme aquí Señor \n a tus plantas hoy, \n pues a ti consagrar quiero,  \n todo lo que soy."}, {"paragraph": "Al contrito has prometido  \n que de Ti no arrojarás, \n hoy propicio eres conmigo,  \n y tu Espíritu me das."}, {"paragraph": "Héme aquí Señor \n a tus plantas hoy, \n pues a ti consagrar quiero,  \n todo lo que soy."}, {"paragraph": "Confesando mis pecados,  \n que sin numero han de ser,  \n y arrojando todo a un lado,  \n a servirte aprenderé."}, {"paragraph": "Héme aquí Señor \n a tus plantas hoy, \n pues a ti consagrar quiero,  \n todo lo que soy."}, {"paragraph": "Mi canción constante sea,  \n y mi sola inspiración,  \n proclamar la dicha entera,  \n del que vive para Dios."}, {"paragraph": "Héme aquí Señor \n a tus plantas hoy, \n pues a ti consagrar quiero,  \n todo lo que soy."}, {"paragraph": "¡Oh, que gozo llena mi alma,  \n al pensar que suyo soy.  \n Y que pronto en las moradas,  \n estaré de mi Señor!"}, {"paragraph": "Héme aquí Señor \n a tus plantas hoy, \n pues a ti consagrar quiero,  \n todo lo que soy."}]'::jsonb, '[]'::jsonb, 'Consagrarme Todo Entero.json'),
('3191fad4-5260-4aa2-ba9a-815872d0c93e', 'HAY UNA SENDA n. 102', 'Hay una senda que el mundo no con...', '--', '[{"paragraph": "Hay una senda que el mundo no conoce \n Hay una senda que yo pude encontrar \n /En cristo tengo la salvación de mi alma \n Cristo es la senda que me puede salvar/"}, {"paragraph": "Hay una senda que el mundo no conoce \n Hay una senda que yo pude encontrar \n /En cristo tengo la salvación de mi alma \n Cristo es la senda que me puede salvar/"}, {"paragraph": "Solamente en Cristo, solamente en Él \n La salvación se encuentra en Él, \n No hay otro nombre dado a los hombres  \n Solamente en Cristo, solamente en Él."}, {"paragraph": "En cristo tengo la salvación de mi alma \n Cristo es la senda que me puede salvar En cristo tengo la salvación de mi alma \n Solamente en Cristo, solamente en Él."}, {"paragraph": "Cuan gloriosa será la mañana, \n Cuando venga Jesús el Salvador. \n Los salvados reunidos como hermanos, bienvenida daremos al Señor."}, {"paragraph": "No habrá necesidad, de la luz el resplandor. \n Ni el sol dará su luz, ni tampoco su calor. \n Allí llanto no habrá, ni tristeza ni dolor, \n Porque entonces Jesús el Rey del cielo,  \n Para siempre será consolador."}, {"paragraph": "Esperamos aquel día glorioso \n Para dar la bienvenida al Dios de amor, \n Donde todo será color de rosa \n En la santa fragancia del Señor."}, {"paragraph": "No habrá necesidad, de la luz el resplandor. \n Ni el sol dará su luz, ni tampoco su calor. \n Allí llanto no habrá, ni tristeza ni dolor, \n Porque entonces Jesús el Rey del cielo,  \n Para siempre será consolador."}, {"paragraph": "El cristiano fiel y verdadero,  \n Y también el obrero de valor, \n Y la iglesia, esposa del Cordero, \n Estarán en los brazos del Señor"}, {"paragraph": "No habrá necesidad, de la luz el resplandor. \n Ni el sol dará su luz, ni tampoco su calor. \n Allí llanto no habrá, ni tristeza ni dolor, \n Porque entonces Jesús el Rey del cielo,  \n Para siempre será consolador."}]'::jsonb, '[]'::jsonb, 'HAY UNA SENDA n. 102.json'),
('25cbcbe3-95a7-4404-adb9-755cc9e911d1', 'CANTARE DE TU AMOR', '//POR MUCHO TIEMPO BUSQUÉ   UNA R...', '--', '[{"paragraph": "//POR MUCHO TIEMPO BUSQUÉ \n UNA RAZÓN DE VIVIR \n EN MEDIO DE MIL PREGUNTAS \n TU AMOR ME RESPONDIÓ"}, {"paragraph": "AHORA VEO LA LUZ \n Y YA NO TENGO TEMOR \n TU REINO VINO A MI VIDA \n Y AHORA VIVO PARA TI"}, {"paragraph": "CANTARÉ DE TU AMOR \n RENDIRÉ MI CORAZÓN ANTE TI \n TU SERÁS MI PASIÓN \n Y MIS PASOS SE GUIARAN POR TU VOZ \n MI JESÚS Y MI REY \n DE TU GRAN AMOR CANTARE//"}]'::jsonb, '[]'::jsonb, 'CANTARE DE TU AMOR.json'),
('bb93f7c0-1e4c-0700-a4a7-234bbe290686', 'HAY UN REDENTOR', 'Hay un redentor es Jesús Dios hijo Es mesías rey', 'C/D|Do-Re', '[{"id": "46fb2b2c-3c25-5648-e19b-3e6df63bbb3e", "paragraph": "Hay un redentor\nes Jesús Dios hijo\nEs mesías rey cordero\nel santísimo.", "chorusPos": [[1]]}, {"id": "6dc19fa5-06a6-e8c9-cc5b-f610cd76d624", "paragraph": "Jesús me redime\nnombre sobre todos;\nÉL ha muerto por nosotros\npor la voluntad de Dios.", "chorusPos": [[1]]}, {"id": "7ac1710c-a549-9971-35da-cebfb0173a6f", "paragraph": "Cuando esté en la gloria\nyo veré su cara\nServiré a mi rey por siempre\nen lugar sagrado.", "chorusPos": [[2]]}]'::jsonb, '[{"choir": "Gracias Padre mío\npor darle a sufrir\nY dejar su Espíritu\ntu obra aquí para cumplir", "id": "d6730ae3-53da-95d0-24b9-dd040b8d4127"}, {"choir": "/ Gracias Padre mío\npor darle a sufrir\nY dejar su Espíritu\ntu obra aquí para cumplir /\n\nY dejar su Espíritu\ntu obra aquí para cumplir.", "id": "a37dbbda-8099-3530-736e-a9b8c487b968"}]'::jsonb, 'HAY UN REDENTOR.json'),
('b8dddf38-1b53-4b79-862c-9b7c04f7fd32', 'enviame señor', 'Envíame Señor, Envíame Señor   En...', '--', '[{"paragraph": "Envíame Señor, Envíame Señor \n Envíame, Señor a predicar \n Y dame tu poder \n Y dame tu poder, \n Y dame tu poder para guiar."}, {"paragraph": "Por sendas de salud \n Por sendas de salud \n Por sendas de salud al pecador \n Envíame, Señor, envíame Señor \n Envíame, Señor a predicar."}]'::jsonb, '[]'::jsonb, 'enviame señor.json'),
('6ab3ab45-e1f5-4a34-8376-8139c79ccc3a', 'A SU NOMBRE GLORIA', 'OH QUE BUENO    ES MI JESUS    QU...', '--', '[{"paragraph": "OH QUE BUENO  \n ES MI JESUS  \n QUE MURIO POR MI  \n EN LA CRUZ  \n MIS PECADOS PERDONO."}, {"paragraph": "/A SU NOMBRE GLORIA \n A SU NOMBRE GLORIA/"}, {"paragraph": "/MARAVILLOSO ES EL SEÑOR \n PODEROSO ES EL SEÑOR/"}, {"paragraph": "/DIOS ESTA PRESENTE  \n PIDAN LO QUE QUIERAN/"}]'::jsonb, '[]'::jsonb, 'A SU NOMBRE GLORIA.json'),
('288e0074-a047-448e-91ea-23ba420ac8a5', 'HAY LIBERTAD', 'Las cadenas de la muerte me quitó...', '--', '[{"paragraph": "Las cadenas de la muerte me quitó \n Para mí ya no hay condenación \n Hay libertad, libertad \n Siendo esclavo del pecado me libró \n En la cruz compró mi redención \n Y libertad, libertad"}, {"paragraph": "Rompió mis cadenas \n Me dio vida nueva \n Y al fondo del mar echó mi maldad \n Lavó mis pecados \n Y me ha perdonado \n Solo en el nombre de Jesús \n Hay libertad"}, {"paragraph": "Yo proclamo al que en la cruz por mí murió \n Y cambió mi duro corazón \n Por libertad, libertad \n El poder de su evangelio me salvó \n Y no me avergüenzo del Señor \n Mi libertad, libertad"}, {"paragraph": "Rompió mis cadenas \n Me dio vida nueva \n Y al fondo del mar echó mi maldad \n Lavó mis pecados \n Y me ha perdonado \n Solo en el nombre de Jesús \n Hay libertad"}, {"paragraph": "Al que el Hijo hace libre \n Es libre en verdad \n Al que el Hijo hace libre \n Es libre en verdad \n Al que el Hijo hace libre \n Es libre en verdad \n Al que el Hijo hace libre \n Es libre en verdad"}, {"paragraph": "Rompió mis cadenas \n Me dio vida nueva \n Y al fondo del mar echó mi maldad \n Lavó mis pecados \n Y me ha perdonado \n Solo en el nombre de Jesús \n Hay libertad"}]'::jsonb, '[]'::jsonb, 'HAY LIBERTAD.json'),
('d78585e4-cf40-99a9-0a49-efeca453dc32', 'NOBLE SOSTÉN', 'Noble sostén de la esperanza mía Fuente bendita,', 'D|Re', '[{"id": "94c39b89-7af2-0ca0-0cae-39e34eb005dd", "paragraph": "Noble sostén de la esperanza mía\nFuente bendita, de vida eterna\nTan solo el alma, que en tus fuerzas fía\nTiene paz, tiene paz.", "chorusPos": [[1]]}, {"id": "f1711d47-479b-d8b4-9a11-e7c4f896b736", "paragraph": "Dura es la lucha, difícil la carrera\nNunca en la lucha desmayar podré\nMi espíritu renuevas con la idea nueva\nDe vencer, de vencer.", "chorusPos": [[1]]}, {"id": "bbbadf30-00fe-acb3-238d-95008e6c2ed1", "paragraph": "Yo soy muy débil, pero en ti soy fuerte\nPues tú me dotas de tu gran poder\nSi tu estás conmigo ni a la misma muerte\nTemeré, no temeré", "chorusPos": [[2]]}]'::jsonb, '[{"choir": "Mi sostén es Jesús\nNunca en la lucha desmayar podré\nMi sostén es Jesús el Señor\nnunca en la lucha desmayar podré", "id": "7d72edf8-bad5-624e-10d8-802d9386a97b"}, {"choir": "Alelu., alelu.,\nnunca en la lucha desmayar podre\n\n/ Alelu., aleluya,\n/ nunca en la lucha desmayar podre / /", "id": "a4782d56-304a-3d78-07ea-c5272d19b2df"}]'::jsonb, 'NOBLE SOSTÉN.json'),
('2657381b-c278-e242-e3bf-7adb10625dab', 'SEÑOR TE NECESITO', 'Me postro hoy, ante ti Y quiero allí, yo descans', 'C|Do', '[{"id": "99577a99-2fee-0d4d-7594-350da62e04e5", "paragraph": "Me postro hoy, ante ti\nY quiero allí, yo descansar\nSin ti señor desecho estoy\nMi corazón tu guiaras", "chorusPos": [[1]]}, {"id": "06687b0a-ca98-4ff3-19bb-9c81ca084d0b", "paragraph": "En mi pecar, tú gracia, es más\nDonde estás Tú, tú gracia está\nY donde estás, yo libre soy\nSantidad es Cristo en mí", "chorusPos": [[1]]}, {"id": "6c1f3732-1c3c-ca79-9e3b-1ef734ea1da7", "paragraph": "Enséñame a cantarte a ti\nAl venir la tentación\nCuando débil soy rendirme a ti\nMi Esperanza y Salvación", "chorusPos": [[1]]}]'::jsonb, '[{"choir": "Oh Señor, te necesito\nen cada momento\nMi defensor\nMi redentor\nDios, te necesito", "id": "7a21ba2d-abe6-f6bc-5baf-7cde30792585"}]'::jsonb, 'SEÑOR TE NECESITO.json'),
('ea0dea0f-c4b5-a2e0-73c3-f4a2c67c031d', 'DE GLORIA EN GLORIA', '/De gloria en gloria te veo, Cuanto más te conoz', 'D|Re', '[{"id": "d2fe3ba3-3676-326c-49cd-5e8792bd29a2", "paragraph": "/De gloria en gloria te veo,\nCuanto más te conozco;\nquiero saber más de ti.\nMi Dios cuán buen alfarero,\nLevántame y transfórmame;\nMoldéame a tu imagen Señor./", "chorusPos": [[1]]}]'::jsonb, '[{"choir": "//Quiero ser más como tú,\nver la vida como tú\nSatúrame de tu espíritu\nY reflejar al mundo tu amor. //", "id": "d83bebbd-f995-76d3-edaf-ee4ce9e49b2c"}]'::jsonb, 'De Gloria en Gloria.json'),
('0b78131d-a741-1d41-9a82-1f5e2a234988', 'AQUELLA CRUZ', 'El cordero que sufrió Traicionado fue El peso de', 'A|La', '[{"id": "fe7c1a78-21ba-4ef0-b672-a0b738fdbb7c", "paragraph": "El cordero que sufrió\nTraicionado fue\nEl peso de nuestra maldad\nFue puesto sobre Él", "chorusPos": [[0]]}, {"id": "3c8b2e54-23be-dd34-d1b4-dee64ffc4b4c", "paragraph": "En silencio soportó\nDolor y humillación\nObediente al Padre fue\nLa cruz por mí cargó", "chorusPos": [[1]]}, {"id": "ffb7f306-96ff-9772-adb6-0ddcd5d9648c", "paragraph": "Unigénito de Dios\nViniste a redimir\nY perdonar a todo aquel\nQue se acerca a ti", "chorusPos": [[1]]}, {"id": "7dd9cf4b-12d5-ea3c-5f29-b709d8be42af", "paragraph": "A la muerte Él venció\nLa tumba abierta está\nAleluya al Salvador\nJesús resucitó", "chorusPos": [[1]]}]'::jsonb, '[{"choir": "En aquella cruz me salvaste\nDerramaste allí tu amor\nMi alma cantará Aleluya\nGloria y honra a ti Señor", "id": "92da4e7e-bdea-5865-e5f4-fce74b7ab3e7"}]'::jsonb, 'Aquella Cruz.json'),
('7be7efc9-3211-4a79-986f-bd88fe15bea1', 'En casa de mi dios', 'Ropa blanca vestiré    /En casa d...', '--', '[{"paragraph": "Ropa blanca vestiré  \n /En casa de mi dios/ \n Allí feliz seré"}, {"paragraph": "una corona llevare   \n /En casa de mi dios/ \n Allí feliz seré"}, {"paragraph": "CON MI HERMANO ANDARÉ  \n /EN CASA DE MI DIOS/ \n ALLÍ FELIZ SERÉ"}, {"paragraph": "UNA ARPA TOCARE    \n /EN CASA DE MI DIOS/ \n ALLÍ FELIZ SERÉ"}, {"paragraph": "CALLES DE ORO ANDARÉ   \n /EN CASA DE MI DIOS/ \n ALLÍ FELIZ SERÉ"}, {"paragraph": "Aguas de vida tomare  \n /En casa de mi dios/  \n alli feliz sere"}, {"paragraph": "EN UN PALACIO HABITARE  \n /EN CASA DE  \n MI DIOS/ \n ALLÍ FELIZ SERÉ"}]'::jsonb, '[]'::jsonb, 'En casa de mi dios.json'),
('17ce943a-93c2-ebab-12cc-f256accbae22', 'EL PODER DE LA CRUZ', 'Oh, el ver aquel negro amanecer Rumbo al calvari', 'G|Sol', '[{"id": "be49237e-f7ae-269b-0f19-57be4b9ea44a", "paragraph": "Oh, el ver aquel negro amanecer\nRumbo al calvario va Jesús\nGrande fue el dolor\ny la humillación\nCuando en la Cruz murió.", "chorusPos": [[1]]}, {"id": "a364db7c-7a4c-b5cf-d21f-94d4aec2ede8", "paragraph": "Oh, ver el dolor que tu faz mostró Cargando\nmi pecado atroz Todo mal pensar, toda\nmala acción Coronaron tu humillación.", "chorusPos": [[1]]}, {"id": "1aa9d0e5-f2ae-9bd6-fb3b-9bc0ad3ad54f", "paragraph": "La tierra tembló, todo oscureció\nSu rostro inclina su Creador\nVelo roto en dos, triunfante exclamo: “Ya\ntodo terminó”", "chorusPos": [[1]]}, {"id": "1fe5aaa6-d11b-2f2c-5654-581e47212950", "paragraph": "Oh mi nombre ver escrito\nen tu cruz\nPorque sufriste libre soy\nYa no moriré, vida me otorgó\nTu generoso amor.", "chorusPos": [[2]]}]'::jsonb, '[{"choir": "El poder de la Cruz:\nmi lugar Él tomó\nMi castigo sufrió,\nEn esa Cruz halle perdón", "id": "90f55883-b079-3449-eca9-2782139ac93f"}, {"choir": "/El poder de la Cruz:\nDios al hijo inmoló\nQue alto precio pagó,\nEn esa Cruz halle perdón./", "id": "1d1c471d-cbd4-a224-afea-e07bae90802e"}]'::jsonb, 'El Poder de la Cruz.json'),
('16485f05-1d28-453e-895b-3f7c98776a22', 'CON CRISTO EN LA FAMILIA', 'CON CRISTO EN LA FAMILIA    UN FE...', '--', '[{"paragraph": "CON CRISTO EN LA FAMILIA  \n UN FELIZ HOGAR  \n QUE FELICIDAD"}]'::jsonb, '[]'::jsonb, 'CON CRISTO EN LA FAMILIA.json'),
('a1cd57df-f1a6-4b54-83c3-c6e0553c7dad', 'En Cristo está mi salvación', 'En Cristo está mi salvación   Ver...', '--', '[{"paragraph": "En Cristo está mi salvación \n Versículo: Hechos 4:12"}, {"paragraph": "En Cristo está mi salvación; \n Él es mi fuerza, luz, canción. \n La Roca Eterna, fundación; \n Firme en prueba y tentación. \n Oh, alto amor, profunda paz; \n La lucha cesa y el temor. \n Mi esperanza y protección. \n En el amor de Cristo estoy."}, {"paragraph": "En Cristo está mi redención; \n Dios infinito se humilló. \n Su don de amor y libertad \n El mundo entero despreció. \n Allá en la cruz, mientras murió, \n El justo Dios se conformó, \n Y mi pecado Él cargó, \n Hoy en Su muerte vivo yo."}, {"paragraph": "Fue sepultado al morir, \n La luz del mundo se apagó. \n Mas con poder resucitó: \n De muerte Él se levantó. \n ¡Glorioso Rey! El Vencedor \n De mi pecado me libró. \n Pues Suyo soy y mío es Él. \n Dios con Su sangre me compró."}, {"paragraph": "Vivir sin culpa y sin temor, \n Es el poder de Cristo en mí. \n Desde nacer hasta morir, \n Cristo conduce mi existir. \n No hay poder ni voluntad \n Que de Él me pueda apartar, \n Hasta que vuelva o muera yo, \n En el poder de Cristo estoy."}]'::jsonb, '[]'::jsonb, 'En Cristo está mi salvación.json'),
('d2e65938-1ea0-637d-f37e-ab83e0864274', 'CORDERO', 'Cordero, que bajaste del cielo   a morir en la c', '_', '[{"id": "af3ffba5-526e-d52d-4ae9-bcb1121y5e32", "paragraph": "Cordero, que bajaste del cielo \n a morir en la cruz \n Para darme la luz \n y tu gran salvación, \n \n vertiste sangre inmaculada \n Con la cual mi maldad, \n al morir en la cruz, \n perdonaste Jesús. \n", "chorusPos": [[1]]}, {"id": "943c1bcd-32a0-0775-19e2-d70b7bf896d7", "paragraph": "Tú eres el que diste a mi vida \n esa paz sin igual, \n Que en el mundo falaz, \n no la pude encontrar. \n  \n Por eso mi alma alegre te canta, \n disfrutando el amor \n Que en la cruz de dolor \n me extendiste, Jesús.", "chorusPos": [[1]]}]'::jsonb, '[{"choir": "Hoy yo te alabo, Señor, \n con todo mi corazón, \n Cordero, porque eres mi Dios \n y mi buen Salvador \n que moriste por mí.", "id": "85fbe665-87b2-0c64-c00a-c23f83e534c1"}]'::jsonb, 'CORDERO.json'),
('de002f37-3c87-f7e3-ada1-887bfe528bfe', 'TODO LO PAGO', 'Puedo oír la voz de Cristo Que me llama hacia Él', 'C|Do', '[{"id": "266dcbbe-35f0-76a1-c1eb-94621ad4737e", "paragraph": "Puedo oír la voz de Cristo\nQue me llama hacia Él,\nTodo cuanto necesito\nLo encuentro sólo en Él", "chorusPos": [[0]]}, {"id": "910a5168-f048-837b-5fd1-7b3ba0495bf6", "paragraph": "Buen pastor, refugio eterno,\nMi todo en todo es Él.\nDe la vida, Él es la fuente,\nMi esperanza en Él pondré.", "chorusPos": [[0]]}, {"id": "3cee88a4-fc6b-ad53-19c7-c9c8872dc197", "paragraph": "Siendo yo su enemigo\nDe mi tuvo compasión,\nRechazaba yo su gracia\nY Él abrió mi corazón.", "chorusPos": [[0]]}, {"id": "9cdc56ac-5803-5c01-2c63-0b75673e4128", "paragraph": "Nada bueno en mi yo encuentro\nMi virtud viene de Él\nY cuando en Él yo esté completo\n/ Para siempre cantaré /", "chorusPos": [[1]]}, {"id": "47c4eaa6-98e7-4e92-44de-9320ce148f5a", "paragraph": "Jesucristo es mi deleite\nGrande gozo tengo en Él\nNada más me satisface\n/ Cristo mi tesoro es /", "chorusPos": [[1], [2]]}]'::jsonb, '[{"choir": "/ Cantaré /\nEl cordero digno es\nSalvador pagó mi deuda\nSe lo debo todo a Él\n\n/ Cantaré /\nSiempre yo le alabaré\nEl mis manchas ha lavado\n/ Suyo siempre yo seré /", "id": "ae038f89-36a6-dfbc-3783-2f8989f70aef"}, {"choir": "Todo lo pago quien por mi murió\nY mis manchas él lavo\n\n/ Con sangre carmesí /", "id": "7bca1e3b-4115-3a17-93d4-09cb471d101c"}]'::jsonb, 'TODO LO PAGO.json'),
('df5ed335-aea4-9ea0-beee-1164c79010cc', 'VIVIR POR FE', 'Por fe, veremos a nuestro Dios En el plan que cr', 'A|La', '[{"id": "74347f40-3670-ce6d-aaa5-a20738931c65", "paragraph": "Por fe, veremos a nuestro Dios\nEn el plan que creó en la eternidad.\nEn la vida de los fieles que llamó\nA vivir por fe y no por ver.", "chorusPos": [[0]]}, {"id": "a846a9d8-be44-b1be-5d59-26336cc8fb69", "paragraph": "Por fe, el justo vivirá\nPor la fe, caminamos junto a el\nComo viendo al invisible protector\nVivir por fe y no por ver", "chorusPos": [[1]]}, {"id": "95d408d3-9afb-5ee1-dbbe-076e9674afc2", "paragraph": "Por fe, profetas hablaron bien\nPor la fe, proclamaron la verdad\nEl Mesías prometido en edén\nEl que la muerte venció en la cruz", "chorusPos": [[0]]}, {"id": "94e202d4-ae52-df8d-20ac-c6fd215f4f46", "paragraph": "Por fe, la iglesia se moverá\nCon poder del espíritu de Dios\nY las fuerzas del infierno no podrán\nDañar la obra de nuestro Dios.", "chorusPos": [[1]]}, {"id": "e55c5c63-949e-92cc-f20b-e7ec65fbc3ed", "paragraph": "Por fe los montes se moverán\nSi la fe permanece en Jesús\nEl poder del evangelio librara\nA todo aquel que confía en él", "chorusPos": [[2]]}]'::jsonb, '[{"choir": "Sus promesas como rocas son,\nSus promesas cumple nuestro Dios\nNos movemos solo por la fe en Él\nVivir por fe y no por ver", "id": "791b4631-0c11-ad2a-2ab0-d470a12773aa"}, {"choir": "/Sus promesas como rocas son,\nSus promesas cumple nuestro Dios\nNos movemos solo por la fe en él\nVivir por fe y no por ver./\n/Vivir por fe y no por ver./", "id": "4cf7bb7c-b1d1-fb75-88c6-716f4100977c"}]'::jsonb, 'VIVIR POR FE.json'),
('84772301-10de-4e2e-9116-2a013f6b96fa', 'Cantemos a Jesús', 'Cantemos a Jesús   Cantemos a Jes...', '--', '[{"paragraph": "Cantemos a Jesús \n Cantemos a Jesús \n Señor de toda creación \n Dios de mi corazón"}, {"paragraph": "Cantemos a Jesús \n Cantemos a Jesús \n Victorioso mas que vencedor \n Rey sobre toda nación"}, {"paragraph": "/Digno de loor/ \n Señor de toda creación \n Dios de mi corazón \n /Digno de loor/ \n Victorioso mas que vencedor \n rey de mi corazón \n (Tu eres el Rey de mi corazón)"}]'::jsonb, '[]'::jsonb, 'Cantemos a Jesús.json'),
('c28cae3f-7802-b276-35c3-7ccc908e9e19', 'DE LA MANO SOBERANA', 'Cuan feroz llega la prueba acechando el corazón ', 'A|La', '[{"id": "e7d3fcda-bb18-63f5-6705-ba991eb9cd4c", "paragraph": "Cuan feroz llega la prueba acechando el corazón\nAmenaza con sus dudas, destruir mi convicción\nCuando todo es incierto; cuando es fácil tropezar\nEl refugio de mi alma, sé que no se moverá.", "chorusPos": [[2]]}, {"id": "5d0c62ab-3037-4dc1-df90-3e73c87f62d7", "paragraph": "Oh cuan altos Sus caminos; cuan supremo es Su plan\nTodo lo ha hecho hermoso en Su tiempo y voluntad\nAunque frágiles mis pasos; limitado mi entender\nSu palabra me asegura: todo obra para bien", "chorusPos": [[2]]}, {"id": "53fd7418-a420-a9f6-79a2-acc3ff1f81a3", "paragraph": "", "chorusPos": [[1], [2], [3]]}]'::jsonb, '[{"choir": "/Venga lo que venga, prevaleceré\nDios es mi esperanza\nSu promesa es ﬁel/", "id": "2bca7eb6-dec8-80dc-70b3-cecc60666e93"}, {"choir": "De la mano soberana de mi Dios me sostendré\nEn Su sabia providencia yo paciente esperaré\nPorque eterna es Su justicia y perfecto Su poder\nÉl ordena mis pasos y\naﬁrmando está mi fe", "id": "26b0a4fe-1c0d-d851-dfb6-e659b57df54c"}, {"choir": "Tú ordenas mis pasos\ny afirmando estás mi fe", "id": "c443420e-4700-e8b8-c62f-ffdb4e4b775a"}]'::jsonb, 'De la Mano Soberana.json'),
('a5f199f0-d6c4-5f89-8665-2458b10b0067', 'CUAN GRANDE ES DIOS', 'Cuan esplendor de un rey vestido de majestad la ', 'E|Mi', '[{"id": "b3eb6b4a-a754-673d-055d-a457912ff704", "paragraph": "Cuan esplendor de un rey\nvestido de majestad la tierra adorará, la tierra adorará.\nRodeado por su luz. tinieblas oscuridad tiembla con su voz.\nTiembla con su voz.", "chorusPos": [[1]]}, {"id": "505fb03e-bd38-ffdb-cf9c-b2d1c9432a75", "paragraph": "Perfecto solo es Él,\nel tiempo suyo es\nprincipio y final, principio y final.\nHermosa trinidad\nsu esencia en tres está.\nCordero vive hoy, cordero vive hoy.", "chorusPos": [[2], [3]]}]'::jsonb, '[{"choir": "Cuán grande es Dios, sin igual,\ncuán grande eres Dios,\ntodos cantarán\ncuán grande eres Dios.", "id": "452239b8-95da-ee5f-c017-5b1ff62f24b0"}, {"choir": "//Cuán grande es Dios, sin igual,\nCuán grande eres Dios, todos cantarán cuán grande eres Dios.//", "id": "2aade3ec-7557-512f-a8ef-d08475571341"}, {"choir": "Nombre sin igual\neres digno de adorar\nsiempre cantare\ncuán grande eres Dios.", "id": "551e0193-7fc5-5950-8d00-19d544193fc4"}]'::jsonb, 'CUAN GRANDE ES DIOS.json'),
('17c90222-bf3c-456b-bf53-d5c9ad4efafc', 'Fuiste a la cruz', '//FUISTE A LA CRUZ   A MORIR  POR...', '--', '[{"paragraph": "//FUISTE A LA CRUZ \n A MORIR  POR MI \n HOY TE AGRADEZCO \n POR AMARME ASÍ"}, {"paragraph": "LE DISTE VALOR \n A MI VIDA SEÑOR \n POR ESO TE ADORO \n TE ADORO CRISTO.// \n FUISTE A LA CRUZ"}, {"paragraph": "TE AMO JESÚS \n ME CAMBIASTE  \n TU A MÍ. \n VEO EL ANTES Y AHORA \n  Y SOY FELIZ."}]'::jsonb, '[]'::jsonb, 'Fuiste a la cruz.json'),
('88cdc5ce-ff16-12ed-aa06-aa19bd141424', 'EN TERNURA', 'En ternura me busco perdido e infeliz Y en sus h', 'G|Sol', '[{"id": "86c4b4b2-5959-cbf2-9d60-3af4f2b69ed7", "paragraph": "En ternura me busco\nperdido e infeliz\nY en sus hombros el me trajo\nDe vuelta a su redil\nMientras los ángeles cantaban\nLa corte celestial sonó", "chorusPos": [[1]]}, {"id": "ffdfe6ff-41e8-2283-c5ec-50ef7448893a", "paragraph": "Murió por mi mientras pecaba\nPobre y ciego fui\nMe hablo para decirme\nSoy suyo me compro\nJamás oi tan dulce voz\nHizo feliz mi corazón", "chorusPos": [[1]]}, {"id": "56532f48-17de-df8b-a7c1-7a25cb605c2c", "paragraph": "Su gracia yo meditare\nY te alabare\nCon asombro te adorare\nY te bendeciré\nParece la eternidad\nMuy corta para adorar", "chorusPos": [[1]]}]'::jsonb, '[{"choir": "Oh oh oh su amor me busco\nOh oh oh su sangre me compro\nOh la gracia que me trajo a su redil\nGracia que me trajo a su redil", "id": "b9e908c6-e7a3-0e45-f7b8-5c18a8942041"}]'::jsonb, 'En Ternura.json'),
('02db95a5-811a-8b42-599b-bbdb7eb36b01', 'BELLAS PALABRAS DE VIDA', 'Oh! cantádmelas otra vez, Bellas palabras de vid', 'A|La', '[{"id": "aca3185f-e9fb-f229-27d2-50eabc4b9bb1", "paragraph": "Oh! cantádmelas otra vez,\nBellas palabras de vida;\nHallo en ellas mi gozo y luz,\nBellas palabras de vida.\nSí, de luz y vida son sostén y guía", "chorusPos": [[1]]}, {"id": "e26f1554-a1ea-08c1-e041-9abdd475e7a1", "paragraph": "Jesucristo a todos da\nBellas palabras de vida;\nOye su dulce voz, mortal,\nbellas palabras de vida.\nBondadoso te salva, y al cielo te llama.", "chorusPos": [[1]]}, {"id": "6a21ec9c-6142-26f1-592b-5775e825b28a", "paragraph": "Grato el cántico sonará,\nBellas palabras de vida;\nTus pecados perdonará,\nbellas palabras de vida.\nSólo Cristo redime, vida nueva te ofrece", "chorusPos": [[1]]}]'::jsonb, '[{"choir": "Qué bellas son, qué bellas son!\nBellas palabras de vida;\nQué bellas son, qué bellas son!\nBellas palabras de vida.", "id": "62c0c73a-b5e2-9619-45fc-e7ca22b22b22"}]'::jsonb, 'Bellas Palabras de Vida.json'),
('eeaf4878-b6af-fd39-f0f6-2789d7fdec08', 'LAVAME EN TU SANGRE', 'Que mi vida entera esté Consagrada a ti, Señor; ', 'A|La', '[{"id": "980ff8e8-a677-bc13-9b82-a7662582caf8", "paragraph": "Que mi vida entera esté\nConsagrada a ti, Señor;\nQue a mis manos pueda guiar\nEl impulso de tu amor.", "chorusPos": [[1]]}, {"id": "8911dc18-9c3a-78f8-0af9-5d0605cc6372", "paragraph": "Que mis pies tan solo en pos\nDe lo santo puedan ir,\nY que, a ti, Señor, mi voz\nSe complazca en bendecir.", "chorusPos": [[1]]}, {"id": "8e128386-a207-9c52-4c6b-3f975d6d3a6a", "paragraph": "Que mi tiempo todo esté\nConsagrado a tu loor.\nQue mis labios, al hablar,\nHablen solo de tu amor", "chorusPos": [[1]]}, {"id": "938178d4-2e63-dd3f-8ff9-fabd91a3e4ab", "paragraph": "Toma, oh Dios, mi voluntad,\nY hazla tuya, nada más.\nToma, sí, mi corazón,\nPor tu trono lo tendrás.", "chorusPos": [[1]]}, {"id": "437e0a11-9145-3328-8cbe-5b4118fff895", "paragraph": "Toma tú mi amor, que hoy\nA tus pies vengo a poner.\nToma todo lo que soy,\nTodo tuyo quiero ser", "chorusPos": [[2]]}]'::jsonb, '[{"choir": "Lávame en tu sangre, Salvador;\nLímpiame de toda mi maldad.\nTraigo a ti mi vida para ser, Señor,\nTuya por la eternidad.", "id": "15eac77b-989a-67ab-f917-32d595142671"}, {"choir": "Lávame en tu sangre, Salvador;\nLímpiame de toda mi maldad.\n/ Traigo a ti mi vida para ser, Señor,\nTuya por la eternidad. /", "id": "00a8b7d3-1a31-298f-2b18-f2569198f3a5"}]'::jsonb, 'LAVAME EN TU SANGRE.json'),
('edc9bc55-6680-4264-ba96-c1590b475a02', 'COMO RELÁMPAGO ASI SERA LA VENIDA DEL SEÑOR', 'COMO RELÁMPAGO ASI SERA LA VENIDA...', '--', '[{"paragraph": "COMO RELÁMPAGO ASI SERA LA VENIDA DEL SEÑOR \n MIRA A TU PUEBLO QUE CLAMANDO ESTA"}]'::jsonb, '[]'::jsonb, 'COMO RELÁMPAGO ASI SERA LA VENIDA DEL SEÑOR.json'),
('8d5fc94b-8d12-44af-a1f6-01e1f78a795d', 'El espiritu de Dios esta en este lugar', '/El espíritu de dios esta en este...', '--', '[{"paragraph": "/El espíritu de dios esta en este lugar \n El espíritu de dios se mueve en este lugar/"}, {"paragraph": "Esta aquí para consolar \n Esta aquí para liberar \n Esta AQUÍ PARA GUIAR  \n EL ESPIRITU DE DIOS ESTA AQUI"}, {"paragraph": "/Muévete en mi/ SEÑOR \n TOCA MI MENTE MI CORAZON  \n LLENA MI VIDA DE TU AMOR \n MUEVETE EN MI DIOS ESPIRITU  \n MUEVETE EN MI"}]'::jsonb, '[]'::jsonb, 'El espiritu de Dios esta en este lugar.json'),
('e420f3b4-f098-43af-b2b6-f80e87732d8f', 'APRENDER A QUERER', 'ESTA VIDA QUE PAREWDCE TAN DIFIFC...', '--', '[{"paragraph": "ESTA VIDA QUE PAREWDCE TAN DIFIFCIL NOS AFLIHE PERNSAR DE NO PODER SALIR  \n QUE NO IMPORTA EL MOMNETO QU TODO TIEMPO TE TENGO  \n ES TU AMOR POR TI YO VIVIRE  \n APRENDER A QUERER APRENDER A CONFIAR NO IMPORTA LO QUE PÀSE AMIGO DE MI ALMA ME MUERO SI NO ESTAS \n HE APRENDIDO QUE NO HAY NADA IM POSIBLE  \n PERO NO IMPORTA EL MOMNETO"}, {"paragraph": "QUE NO IMPORTA EL MOMENTO QUE TODO TIEMPO TE TENGO  \n ES TU AMOR POR TI YO VIVIRE  \n APRENDER A QUERER  \n APRENDER A CONFIAR  \n NO IMPORTA LO QUE PÀSE AMIGO DE MI ALMA  \n ME MUERO SI NO ESTAS"}, {"paragraph": "ESTA VIDA QUE PAREWDCE TAN DIFIFCIL NOS AFLIHE PERNSAR DE NO PODER SALIR  \n QUE NO IMPORTA EL MOMNETO QU TODO TIEMPO TE TENGO  \n ES TU AMOR POR TI YO VIVIRE  \n APRENDER A QUERER APRENDER A CONFIAR NO IMPORTA LO QUE PÀSE AMIGO DE MI ALMA ME MUERO SI NO ESTAS \n PERO NO IMPORTA EL MOMNETO"}]'::jsonb, '[]'::jsonb, 'APRENDER A QUERER.json'),
('242e94b0-9c22-1d34-e3ab-0f7fd9633bb6', 'EL DIOS QUE ADORAMOS', 'El Dios que hizo los cielos y la tierra Con el p', 'F#|Fa#', '[{"id": "9cc718eb-9b52-4da7-6996-b21a65ecc8c4", "paragraph": "El Dios que hizo\nlos cielos y la tierra\nCon el poder de Su palabra\nReina con autoridad", "chorusPos": [[0]]}, {"id": "db092dc2-aa87-08f3-cc3a-e4a4df9203ba", "paragraph": "El Dios que aún\nlos vientos le obedecen\nUna palabra es suficiente\nPara los muertos levanta", "chorusPos": [[1]]}, {"id": "37bde357-f6f6-7ddb-b7df-6cb43d31e0ad", "paragraph": "Tú eres el Dios que adoramos\nTodopoderoso y soberano\nGrande en misericordia y poder para salvar", "chorusPos": [[0]]}, {"id": "2787ebe7-481f-f438-3a48-474aa7422894", "paragraph": "Tú eres el Dios que adoramos\nQuien derrotó la muerte\ny el pecado\nGlorioso Redentor y Rey,\nTe adoramos", "chorusPos": [[0]]}, {"id": "1177243f-14cf-26ee-6342-727438b7dc02", "paragraph": "El Dios que descendió desde Su trono\nPara llevar sobre Sus hombros\nNuestra culpa y transgresión\nJesús, exaltado sobre todo\nNombre sobre todo nombre\nSolo en Él hay salvación.\n\nA Él sea la gloria y el poder\nTodo es de Él y para Él", "chorusPos": [[0]]}]'::jsonb, '[{"choir": "Nadie es como El, oh gran YO SOY", "id": "febb57d1-1957-1037-ed9e-885188f14850"}]'::jsonb, 'El Dios que Adoramos.json'),
('12ffef4b-31fc-4a29-bc84-c141488937de', 'DIOS PODEROSO', '¿Quién sino el Señor   Las estrel...', '--', '[{"paragraph": "¿Quién sino el Señor \n Las estrellas creó \n Y su luz limitó?"}, {"paragraph": "¿Quién sino el Señor \n Sol y Luna formó \n Movimiento les dio?"}, {"paragraph": "¿Quién sino el Señor \n Hace la lluvia venir \n Truenos rugir? \n Tus obras grandes son"}, {"paragraph": "Dios poderoso \n Tú gobiernas la creación \n Con tu palabra, Señor \n Te exaltaremos \n Dios poderoso \n De ti canta la creación \n Llenas todo tú, Señor \n Te exaltaremos \n Por siempre y siempre, oh Dios"}, {"paragraph": "¿Quién sino el Señor \n Ha soñado en el plan \n Para al hombre salvar?"}, {"paragraph": "¿Quién sino el Señor \n Limpiará al pecador \n Con su sangre y amor?"}, {"paragraph": "¿Quién sino el Señor \n Puede dar vida y salvar \n Por una cruz? \n Tus planes grandes son"}, {"paragraph": "Dios poderoso \n Tú gobiernas la creación \n Con tu palabra, Señor \n Te exaltaremos \n Dios poderoso \n De ti canta la creación \n Llenas todo tú, Señor \n Te exaltaremos \n Por siempre y siempre, oh Dios"}, {"paragraph": "Todas las cosas \n Vienen de ti y por ti \n Oh gran yo soy \n Todo es tuyo \n Y para ti, oh Señor \n Oh gran yo soy"}, {"paragraph": "Dios poderoso \n Tú gobiernas la creación \n Con tu palabra, Señor \n Te exaltaremos \n Dios poderoso \n De ti canta la creación \n Llenas todo tú, Señor \n Te exaltaremos \n Por siempre y siempre, oh Dios \n *"}]'::jsonb, '[]'::jsonb, 'DIOS PODEROSO.json'),
('d2e65938-1ea0-637d-f37e-ab83e0864275', 'SU GRACIA ES MAYOR', '¿Qué amor mis pecados decide olvidar?   Lanzados', 'E', '[{"id": "af3ffba5-526e-d52d-4ae9-acb1121y5e32", "paragraph": "¿Qué amor mis pecados decide olvidar? \n Lanzados al mar no los quiere contar. \n Él siendo omnisciente olvida mi error, \n mis faltas son muchas, Su gracia es mayor.", "chorusPos": [[1]]}, {"id": "943c1bcd-32a0-0775-19e2-a70b7bf896d7", "paragraph": "Paciente me aguarda en mi desviar, \n Un padre que tierno me llama al hogar. \n Recibe al débil y vil pecador, \n mis faltas son muchas, Su gracia es mayor.", "chorusPos": [[1]]}, {"id": "943c1bcd-32a0-0775-19e2-b70b7bf896d7", "paragraph": "Que grandes riquezas, Él nos otorgó, \n Su sangre fue el pago, su vida entregó. \n Pagó esa deuda y la canceló, \n mis faltas son muchas, Su gracia es mayor.", "chorusPos": [[1, 2], [2, 2]]}]'::jsonb, '[{"choir": "Gloria a Dios, \n Su gracia es mayor, \n Sus misericordias hoy nuevas son, \n mis faltas son muchas, Su gracia es mayor", "id": "85fbe665-87b2-0c64-c00a-a23f83e534f1"}, {"choir": "mis faltas son muchas, Su gracia es mayor.", "id": "85fbe665-87b2-0c64-c00a-t23f83e534f1"}]'::jsonb, 'SU GRACIA ES MAYOR.json'),
('fc761b89-4cf1-4b9a-8342-a8924539adbf', 'al taller del maestro', 'Hay como me duele estar despierto...', '--', '[{"paragraph": "Hay como me duele estar despierto y no poder cantar  \n Como expresarte sin palabras, me muero siu no estas  \n El tiempo pasa y todo cambia, hoy lloro  de soledad; \n El sueño que llevo en el alma de repente ya no está \n Que la sonrisa se a marchado// mis lagrimas caerán.//"}, {"paragraph": "Al taller del maestro vengo, pues el me curara  \n Me tomara entre sus brazos y cada herida sanará \n Las herramientas del maestro, mi alma el remendará  \n Martillo en mano y mucho fuego, aunque me duele ayudara…..  \n A conocerlo y a entenderlo, a saber que nada merezco,  \n amar es mas que un pretexto, es una entrega, es un negar"}, {"paragraph": "Mas que aquel sentimiento, es la decisión de amar…. \n Al taller del maestro vengo, ahí el sol se pondrá \n Al taller del maestro vengo, no importa el tiempo allí he de estar  \n Al taller del maestro vengo…. \n Ay de aquellos días que hizo frio, el sol no apareció,  \n Cuando el talento no lo es todo y el silencio vale mas"}, {"paragraph": "Hay como me duele estar despierto y no poder cantar  \n Como expresarte sin palabras, me muero siu no estas  \n El tiempo pasa y todo cambia, hoy lloro  de soledad; \n El sueño que llevo en el alma de repente ya no está \n Que la sonrisa se a marchado// mis lagrimas caerán.//"}]'::jsonb, '[]'::jsonb, 'al taller del maestro.json'),
('e4f46615-fdb2-31c2-b1fc-d4977bc9835d', 'MARAVILLOSO ES EL GRAN AMOR', 'Maravilloso es el gran amor que Cristo el Salvad', '_', '[{"id": "72e778f9-b973-0fdc-9293-839f5a697b27", "paragraph": "Maravilloso es el gran amor que Cristo el Salvador\nderramó en mí; Siendo rebelde y pecador,\nyo de su muerte causa fui. ¡Grande, sublime,\ninmensurable amor! Por mí murió el Salvador.", "chorusPos": [[1]]}, {"id": "f77d4c2c-f56b-c515-a55f-d8c1650d52b7", "paragraph": "El su celeste hogar abandonó, dejando posición,\ngloria y honor; De todo ello se despojó.\npor rescatar al pecador. Misericordia inmensa\nél mostró; su gran amor me alcanzó.", "chorusPos": [[1]]}, {"id": "e8b1c2de-e4a3-c382-394a-efac3a685771", "paragraph": "¡Grande misterio! Dios el inmortal muriendo en la\ncruz entregó su ser; ni mente humana ni angelical\njamás lo puede comprender. Inexplicable\nes el infinito amor que demostró mi Salvador.", "chorusPos": [[1]]}, {"id": "501b7168-aa9e-1d8e-06c9-64c75841295c", "paragraph": "En vil prisión mi alma padeció, atada en pecado\ny oscuridad; pronto en mi celda resplandeció\nla clara luz de su verdad. Cristo las férreas\ncadenas destruyó; Quedó ya libre, ¡Gloria a Dios!", "chorusPos": [[1]]}, {"id": "088df862-22ea-4219-ae28-2a82d85bff65", "paragraph": "Hoy ya no temo la condenación; Jesús\nes mi Señor, y yo suyo soy.\nVivo en élque es mi salvación,\nvestido en su justicia voy.\nLibre acceso al Padre gozo ya\ny entrada al trono celestial.", "chorusPos": [[1]]}]'::jsonb, '[{"choir": "¡Oh, maravilla de su amor,\npor mí murió el Salvador!", "id": "45ec4505-9d59-123c-838e-4ed71fd7fcd9"}]'::jsonb, 'MARAVILLOSO ES EL GRAN AMOR.json'),
('1ebc4cab-a5ad-44cb-9f4a-fd4da9c48a26', 'cena del señor', 'ÉL HA SIDO    FIEL...', '--', '[{"paragraph": "ÉL HA SIDO  \n FIEL"}, {"paragraph": "Día a día Tú has sido fiel, no has cambiado y no cambiarás     \n Maravillado estoy con tu amor porque me amaste siendo un pecador"}, {"paragraph": "Cuando recuerdo mi vida sin ti, sin esperanza en sombras viví     \n Más hoy reboso en gracia y perdón, porque adoptaste a un vil pecador"}, {"paragraph": "Te alabaré, te glorificaré             \n  Porque agradecido estoy  \n por tu inmenso amor  \n Te alabaré, te glorificaré         \n Porque tu hijo soy, te alabaré"}, {"paragraph": "Cuando en prueba te exaltaré,  \n y cuando duela en ti confiaré   \n Porque conozco tu inmensa bondad y sé que nunca me abandonarás"}, {"paragraph": "Te alabaré, te glorificaré             \n  Porque agradecido estoy  \n por tu inmenso amor  \n Te alabaré, te glorificaré         \n Porque tu hijo soy, te alabaré"}, {"paragraph": "Toda mi vida la pongo a tus pies, has lo que quieras con ella mi Rey                                                             \n Hasta que vuelvas con fe cantaré, “Día a día tú has sido fiel”"}, {"paragraph": "Te alabaré, te glorificaré             \n  Porque agradecido estoy  \n por tu inmenso amor  \n Te alabaré, te glorificaré         \n Porque tu hijo soy, te alabaré"}]'::jsonb, '[]'::jsonb, 'cena del señor.json'),
('dab8372e-87b2-7802-cf4e-c2c7ba899ac4', 'TU NOMBRE LEVANTARE', '//Tú nombre levantaré, me deleito en adorarte. T', 'G|Sol', '[{"id": "303e50ea-904f-017b-f73f-50f8ed430502", "paragraph": "//Tú nombre levantaré,\nme deleito en adorarte.\nTe agradezco que en mi vida estés,\nque vinieras a salvarme//.", "chorusPos": [[1]]}]'::jsonb, '[{"choir": "//Dejaste el trono para,\nmostrarnos la luz\nDe Tú trono a la cruz,\ny mi deuda pagar.\nDe la cruz a morir,\nde la muerte a tú trono;\nTú nombre levantaré//.", "id": "663e9947-17f3-73ad-9143-5b3d3862b13e"}]'::jsonb, 'TU NOMBRE LEVANTARE.json'),
('68ff5d82-7808-41ba-8010-0aaa49d51d70', 'HE DECIDIDO SEGUIR A CRISTO', '// He decidido seguir a Cristo. // / No vuelvo a', 'C|Do', '[{"id": "3883c6e8-cc1a-d3cb-22b3-b3d03125a637", "paragraph": "\n// He decidido seguir a Cristo. //\n/ No vuelvo atrás; no vuelvo atrás. /", "chorusPos": [[0]]}, {"id": "17529ab3-ef32-bf8e-20c2-3a5d2e93cfda", "paragraph": "// El Rey de gloria me ha transformado. //\n/ No vuelvo atrás; no vuelvo atrás. /", "chorusPos": [[0]]}, {"id": "4cc7a4c6-471f-531f-8828-14c821295c11", "paragraph": "// En mis tristezas me da consuelo. //\n/ No vuelvo atrás; no vuelvo atrás. /", "chorusPos": [[0]]}, {"id": "74ef6925-609a-5ca9-141d-5ab3897150c0", "paragraph": "// La cruz delante, el mundo atrás. //\n/ No vuelvo atrás; no vuelvo atrás. /", "chorusPos": [[0]]}]'::jsonb, '[]'::jsonb, 'He Decidido Seguir a Cristo.json'),
('41738fef-e7cb-4a73-8441-c4b05bfcb3b8', 'EN LA CASA DE MI PADRE', 'EN LA CASA DE MI PADRE   /HAY LUG...', '--', '[{"paragraph": "EN LA CASA DE MI PADRE \n /HAY LUGAR PARA TODOS/"}, {"paragraph": "PARA EL RICO  \n PARA EL POBRE  \n HAY LUGAR PARA TODOS"}, {"paragraph": "PARA EL NIÑO  \n PARA EL ANCIANO  \n /HAY LUGAR PARA TODOS/"}, {"paragraph": "PARA EL NEGRO  \n PAR EL BLANCO  \n /HAY LUGAR PARA TODOS/"}, {"paragraph": "PARA EL BLANCO \n PARA EL NEGRO \n /HAY LUGAR PARA TODOS/"}, {"paragraph": "PARA EL ALTO  \n PAR EL BAJO  \n /HAY LUGAR PARA TODOS/"}, {"paragraph": "PARA EL ALTO PARA EL BAJO HAY LUGAR PARA TODOS"}, {"paragraph": "EN ALACASA DEMI PADRE HAY LUGAR PARA TODO S \n PARA EL RICO  \n PARA EL POBRTE  \n HAY LUGAR PARA TODO  \n PARA EL NIÑO PAR EL VIEJO HAY LUGAR PARA TODOS \n PARA EL NEGRO  \n PAR EL BLANCO HAY LUGAR PARA TODOS \n HAY LUGAR PARA TODO PARA EL ALTO PARA EL BAJO HAY LUGAR PARA TODOS"}]'::jsonb, '[]'::jsonb, 'EN LA CASA DE MI PADRE.json'),
('059aa4cd-4be7-481b-b0e9-4e3073fe5099', 'EL SEÑOR YA VIENE PRONTO', '/EL SEÑOR YA VIENE PRONTO Y SU PU...', '--', '[{"paragraph": "/EL SEÑOR YA VIENE PRONTO Y SU PUEBLO YA ESTA LISTO/ \n /TENGO PAZ TENGO AMOR \n CON MI SALVADOR/"}, {"paragraph": "/LLEVAREMOS SU PALABRA \n TODOS JUNTOS SIN NINGUN TEMOR/  \n /TENGO PAZ TENGO AMOR \n CON MI SALVADOR/"}]'::jsonb, '[]'::jsonb, 'EL SEÑOR YA VIENE PRONTO.json'),
('9c70711b-f4da-406b-aff8-4416c7ff03c6', 'CUANDO ESTABA YO', '/Cuando estaba yo    lejos del Se...', '--', '[{"paragraph": "/Cuando estaba yo  \n lejos del Señor/ \n /Cayó la buena semilla  \n en mi corazón/"}, {"paragraph": "/Bendito Señor, bendito Jesús/ \n /La honra y la gloria sean para ti/ \n /Esa semilla fue  \n la palabra de Dios/ \n /Que cambió mi vida para  \n la gloria de Dios/"}]'::jsonb, '[]'::jsonb, 'CUANDO ESTABA YO.json'),
('6c76749f-5f1b-4ba2-a470-a7bfe9ceb8eb', 'ERES TODO PODEROSO', 'La única razón de mi adoración   ...', '--', '[{"paragraph": "La única razón de mi adoración \n Eres tu mi Jesús \n Mi único motivo para vivir      \n  eres tu mi Señor."}, {"paragraph": "Mi única verdad esta en ti  \n Eres mi luz y mi salvación \n Mi único amor eres tu Señor  \n Y por siempre te alabare."}, {"paragraph": "Eres Todo poderoso  \n Eres grande y majestuoso  \n Eres fuerte invencible  \n Y no hay nadie como tu."}, {"paragraph": "Tu eres Todo poderoso  \n Eres grande y majestuoso  \n Eres fuerte invencible  \n Y no hay nadie como tu."}, {"paragraph": "No hay nadie mas  \n que este con vos  \n ehhhehhh a ti a ti OOOOHOOOOO"}]'::jsonb, '[]'::jsonb, 'ERES TODO PODEROSO.json'),
('0419cc77-146f-de73-460d-e3696f9a9cd8', 'LA HERMOSA VISIÓN DE LA CRUZ', 'Largos años vague por el valle del mal, sin cons', 'A|La', '[{"id": "f87d0cd9-9269-720f-325d-1e3c5e6288d6", "paragraph": "Largos años vague\npor el valle del mal,\nsin consuelo, sin fe, sin amor\n\nY la sombra fatal\nde la senda que hollé,\npuso en mi alma la hiel del dolor.", "chorusPos": [[1]]}, {"id": "7fe5a351-f02e-f39c-9c71-ab3400d14bc3", "paragraph": "Desde entonces, por Él,\nya no soy lo que fui,\nuna sombra sin Dios y sin ley.\n\nMi existencia le di,\ny le quiero ser fiel;\nme constriñe el amor de mi Rey.", "chorusPos": [[1]]}, {"id": "b921f8d6-ec35-283f-732c-cb5b687926dc", "paragraph": "Peregrino que vais\npor el valle del mal,\nvuestra senda solo es de dolor\n\nEsa carga fatal\nque en el alma lleváis,\nven y ponla a los pies del Señor.", "chorusPos": [[1]]}]'::jsonb, '[{"choir": "A mis pies el infierno se abrió,\ny clamé con el alma a Jesús.\nY al instante la escena cambió,\nen la hermosa visión de la cruz.", "id": "b6178953-51f2-dc81-1aab-5dd55b2f2a5a"}]'::jsonb, 'LA HERMOSA VISIÓN DE LA CRUZ.json'),
('46b597ca-829a-44e1-9c1c-638c98326034', 'HAY UNA PROMESA EN LA BIBLIA', '/Hay una promesa en la Biblia   Q...', '--', '[{"paragraph": "/Hay una promesa en la Biblia \n Que es para ti y para mi/ \n /Cielo nuevo y tierra nueva \n donde vamos a vivir/"}, {"paragraph": "/Saltando hermanos saltando \n Saltando hermanos saltando \n Saltando hermanos saltando \n Como corderos de la manada/"}, {"paragraph": "Así, así, así,  \n así se alaba a Dios \n Así, así, así,  \n así se alaba a Dios \n Pero que lindo se ve  \n el pueblo de Dios"}, {"paragraph": "Maravilloso se ve el  \n pueblo de Dios  \n Pero que alegre se ve  \n el pueblo de Dios \n Pero que chévere se ve  \n el pueblo de Dios"}, {"paragraph": "/Y dando la media vueltita \n Y dando la media vueltita \n Y dando la media vueltita \n La vuelta entera de la victoria/"}]'::jsonb, '[]'::jsonb, 'HAY UNA PROMESA EN LA BIBLIA.json')
